INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C1','math',2,1,'u1',2,'백 알아보기 — 10이 10개인 수 100을 쓰고 「백」으로 읽으며, 99보다 1만큼·90보다 10만큼 더 큰 수로 나타내기',ARRAY['2수01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C2','math',2,1,'u1',3,'몇백 알아보기 — 100이 몇 개인지로 200~900을 쓰고 읽으며, 몇백이 100이 몇 개인지 거꾸로 알기',ARRAY['2수01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C3','math',2,1,'u1',4,'세 자리 수 쓰고 읽기 — 100·10·1의 개수(수 모형·동전)로 세 자리 수를 쓰고 읽으며, 없는 자리에는 0을 쓰고 0인 자리는 읽지 않기',ARRAY['2수01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C4','math',2,1,'u1',5,'각 자리의 숫자가 나타내는 값 — 백·십·일의 자리 숫자를 찾고, 같은 숫자라도 자리에 따라 값이 다름을 알며, 세 자리 수를 각 자리 값의 합으로 나타내기',ARRAY['2수01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C5','math',2,1,'u1',6,'뛰어 세기 — 100씩·10씩·1씩 뛰어 세고 거꾸로 세며, 몇씩 뛰었는지 찾고, 윗자리가 바뀌는 문턱(390→400, 999→1000) 넘기',ARRAY['2수01-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C6','math',2,1,'u1',7,'세 자리 수의 크기 비교 — 높은 자리부터 차례로 견주어 >·<로 나타내고, 셋 가운데 가장 큰/작은 수와 수 카드로 가장 큰/작은 수 찾기',ARRAY['2수01-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u1-C7','math',2,1,'u1',9,'수를 여러 가지로 나타내기 — 한 수를 100·10·1의 여러 묶음(10이 몇 개, 동전 바꾸기)으로 나타내고, 한 자리에 10개가 넘게 모이면 윗자리로 바꾸어 세기',ARRAY['2수01-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X01','math',2,'u1',ARRAY['M2-1-u1-C1','M2-1-u1-C5']::text[],'9 다음에 윗자리가 바뀌는 것을 모르고 숫자를 이어 붙인다 — 99 다음을 910, 390에서 10 더를 3100, 999 다음을 9910','수 모형으로 9개 다음 1개를 더 놓고, 10개가 되면 윗자리 모형 1개로 바꾸는 장면을 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X02','math',2,'u1',ARRAY['M2-1-u1-C1','M2-1-u1-C7']::text[],'10이 10개를 1010이나 20처럼 늘어놓거나, 100 속에 10이 몇 개 있는지 모른다','십 모형 10개를 백 모형 1개 위에 겹쳐 놓아 크기가 같음을 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X03','math',2,'u1',ARRAY['M2-1-u1-C2','M2-1-u1-C7']::text[],'100의 개수를 다른 자리에 쓴다 — 100이 5개를 105·50으로, 600을 100이 60개로','백·십·일 칸을 그려 놓고 「100이 몇 개」는 백의 칸에만 쓰게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X04','math',2,'u1',ARRAY['M2-1-u1-C3','M2-1-u1-C4']::text[],'없는 자리의 0을 빠뜨린다 — 백 5·일 3을 53으로, 「구백이」를 92로','세 칸을 먼저 그리고 빈 칸에 0을 채우는 습관 들이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X05','math',2,'u1',ARRAY['M2-1-u1-C3','M2-1-u1-C4']::text[],'읽은 소리나 각 자리 값을 그대로 이어 쓴다 — 이백오십사를 200504로, 300+40+7을 300407로','세 자리 수는 숫자 세 개 — 칸 하나에 숫자 하나만 들어간다는 것을 수 카드 세 장으로 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X06','math',2,'u1',ARRAY['M2-1-u1-C3']::text[],'자리 순서를 섞어 쓴다 — 백 3·십 4·일 7을 743으로','「백·십·일」을 왼쪽부터 손가락으로 짚으며 숫자를 놓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X07','math',2,'u1',ARRAY['M2-1-u1-C1','M2-1-u1-C2','M2-1-u1-C3']::text[],'읽을 때 자리 이름을 빼먹거나 0을 읽는다 — 254를 「이오사」, 507을 「오백영칠」','숫자 뒤에 자리 이름(백·십)을 붙여 끊어 읽고, 0인 자리는 건너뛰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X08','math',2,'u1',ARRAY['M2-1-u1-C4']::text[],'자리 이름을 헷갈린다 — 오른쪽부터 세어 백의 자리와 일의 자리를 바꾸거나, 십의 자리 숫자를 다른 자리 값으로 읽는다','자릿값 표에 수를 써 넣고 「왼쪽이 백」을 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X09','math',2,'u1',ARRAY['M2-1-u1-C4']::text[],'숫자와 그 숫자가 나타내는 값을 같게 본다 — 382의 8을 8로, 323의 두 3을 같은 값으로','「숫자 × 자리」로 값을 말하게 하기 — 8은 십의 자리라서 80') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X10','math',2,'u1',ARRAY['M2-1-u1-C3','M2-1-u1-C7']::text[],'한 자리에 10개가 넘게 모여도 윗자리로 바꾸지 않는다 — 10이 13개·1이 2개를 1132나 32로','10개씩 묶어 윗자리 모형 하나로 바꾼 뒤 다시 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X11','math',2,'u1',ARRAY['M2-1-u1-C5']::text[],'뛰어 셀 때 다른 자리 숫자를 바꾼다 — 10씩 뛰는데 일의 자리나 백의 자리를 1 바꿈','「10씩이면 십의 자리만 움직인다」 — 바뀌는 자리에 색칠하며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X12','math',2,'u1',ARRAY['M2-1-u1-C1','M2-1-u1-C5']::text[],'1·10·100 가운데 얼마만큼인지, 몇씩 뛰었는지를 헷갈리거나 방향을 거꾸로 한다','이웃한 두 수에서 바뀐 자리를 찾아 「그 자리만큼」이라고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X13','math',2,'u1',ARRAY['M2-1-u1-C6']::text[],'낮은 자리부터 견준다 — 일의 자리가 큰 169가 196보다 크다고 한다','두 수를 자릿값 표에 위아래로 써 놓고 백의 자리부터 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X14','math',2,'u1',ARRAY['M2-1-u1-C6']::text[],'>·< 기호의 방향을 거꾸로 쓴다','벌어진 입이 큰 수를 먹는다 — 큰 수 쪽이 벌어진 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X15','math',2,'u1',ARRAY['M2-1-u1-C6','M2-1-u1-C7']::text[],'묻는 말을 거꾸로 읽는다 — 가장 큰↔가장 작은, 더 필요한 수↔전체 수','물음의 「큰·작은·더」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u1-X16','math',2,'u1',ARRAY['M2-1-u1-C6']::text[],'수 카드로 수를 만들 때 높은 자리부터 놓지 않거나 0을 맨 앞에 놓는다','백의 자리부터 차례로 — 가장 작은 수를 만들 때 0은 백의 자리에 못 온다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#1','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',1,'mc','auto','십 모형 10개가 있어요. 모두 얼마인가요?',ARRAY['M2-1-u1-X02']::text[],true,'{"seq":1,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"십 모형 10개가 있어요. 모두 얼마인가요?","options":[{"t":"100","correct":true},{"t":"1010","mis":"M2-1-u1-X02"},{"t":"10","mis":"M2-1-u1-X02"}],"explanation":["십 모형 하나는 10이에요.","10이 10개이면 100이에요.","십 모형 10개는 백 모형 1개와 같아요."],"asset":{"type":"blocks3","h":0,"t":10,"o":0},"variant_rule":{"alt":[{"stem":"10원짜리 동전 10개는 모두 얼마인가요?","options":[{"t":"100원","correct":true},{"t":"1010원","mis":"M2-1-u1-X02"},{"t":"10원","mis":"M2-1-u1-X02"}],"explanation":["10원짜리 하나는 10원이에요.","10원이 10개이면 100원이에요.","10원짜리 10개는 100원짜리 1개와 같아요."],"asset":{"type":"blocks3","h":0,"t":10,"o":0,"unit":"coin"}},{"stem":"구슬이 10개씩 10봉지 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"100","correct":true},{"t":"20","mis":"M2-1-u1-X02"},{"t":"1010","mis":"M2-1-u1-X02"}],"explanation":["한 봉지에 10개씩이에요.","10이 10개이면 100이에요.","봉지 수와 구슬 수를 헷갈리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#2','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',1,'sa','auto','10이 10개이면 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u1-C1","difficulty":1,"kind":"sa","stem":"10이 10개이면 얼마인가요?","answer":["100"],"explanation":["10씩 세어 보세요 — 10, 20, … 90, 100.","10이 10개이면 100이에요.","100은 「백」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"99보다 1만큼 더 큰 수는 얼마인가요?","answer":["100"],"explanation":["99 바로 다음 수를 찾아요.","99보다 1 큰 수는 100이에요.","99 다음은 910이 아니라 100이에요."]},{"stem":"90보다 10만큼 더 큰 수는 얼마인가요?","answer":["100"],"explanation":["90에서 10을 더 뛰어 세어요.","90보다 10 큰 수는 100이에요.","십 모형 9개에 1개를 더하면 10개 — 100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#3','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',1,'mc','auto','100을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u1-X07','M2-1-u1-X02']::text[],true,'{"seq":3,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"100을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"백","correct":true},{"t":"일영영","mis":"M2-1-u1-X07"},{"t":"십십","mis":"M2-1-u1-X02"}],"explanation":["100은 백의 자리가 1인 수예요.","「백」이라고 읽어요.","숫자를 하나씩 따로 읽지 않아요."],"variant_rule":{"alt":[{"stem":"「백」을 수로 쓰면 무엇인가요?","options":[{"t":"100","correct":true},{"t":"1","mis":"M2-1-u1-X03"},{"t":"10","mis":"M2-1-u1-X02"}],"explanation":["「백」은 10이 10개인 수예요.","수로 쓰면 100이에요.","1 뒤에 0을 두 개 써요."]},{"stem":"100에 대한 설명으로 바른 것은 어느 것인가요?","options":[{"t":"99보다 1 큰 수예요.","correct":true},{"t":"90보다 1 큰 수예요.","mis":"M2-1-u1-X12"},{"t":"10이 1개인 수예요.","mis":"M2-1-u1-X02"}],"explanation":["100은 99 바로 다음 수예요.","90보다는 10 커요.","10이 10개 모여야 100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#4','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',1,'mc','auto','99보다 1만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X12']::text[],true,'{"seq":4,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"99보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X01"},{"t":"98","mis":"M2-1-u1-X12"}],"explanation":["99 다음 수를 찾아요.","99보다 1 큰 수는 100이에요.","9 뒤에 10을 붙이지 않아요 — 십 모형이 10개가 되어 백 모형 1개가 돼요."],"variant_rule":{"alt":[{"stem":"98, 99 다음에 오는 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X01"},{"t":"990","mis":"M2-1-u1-X01"}],"explanation":["99 다음 수예요.","99보다 1 큰 수는 100이에요.","일의 자리·십의 자리가 모두 9이면 다음은 100이에요."]},{"stem":"100보다 1만큼 더 작은 수는 무엇인가요?","options":[{"t":"99","correct":true},{"t":"101","mis":"M2-1-u1-X12"},{"t":"90","mis":"M2-1-u1-X12"}],"explanation":["100 바로 앞의 수예요.","100보다 1 작은 수는 99예요.","1만큼은 바로 앞, 10만큼은 십 모형 하나 차이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#5','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'mc','auto','100은 90보다 얼마만큼 더 큰 수인가요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":5,"concept":"M2-1-u1-C1","difficulty":2,"kind":"mc","stem":"100은 90보다 얼마만큼 더 큰 수인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X12"},{"t":"100","mis":"M2-1-u1-X12"}],"explanation":["90에서 10씩 뛰어 세면 바로 100이에요.","그래서 100은 90보다 10 큰 수예요.","십 모형 9개에 1개를 더하면 10개예요."],"variant_rule":{"alt":[{"stem":"100은 99보다 얼마만큼 더 큰 수인가요?","options":[{"t":"1","correct":true},{"t":"10","mis":"M2-1-u1-X12"},{"t":"9","mis":"M2-1-u1-X12"}],"explanation":["99 바로 다음 수가 100이에요.","그래서 100은 99보다 1 커요.","바로 다음 수는 1 큰 수예요."]},{"stem":"100은 80보다 얼마만큼 더 큰 수인가요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M2-1-u1-X12"},{"t":"10","mis":"M2-1-u1-X12"}],"explanation":["80, 90, 100 — 10씩 두 번 뛰어요.","그래서 100은 80보다 20 커요.","10씩 몇 번 뛰었는지 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#6','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'mc','auto','100은 10이 몇 개인 수인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X09']::text[],true,'{"seq":6,"concept":"M2-1-u1-C1","difficulty":2,"kind":"mc","stem":"100은 10이 몇 개인 수인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X02"},{"t":"100","mis":"M2-1-u1-X09"}],"explanation":["10, 20, 30, … 100 — 10씩 세어 보세요.","10번 세면 100이에요.","그래서 100은 10이 10개예요."],"variant_rule":{"alt":[{"stem":"구슬 100개를 10개씩 묶으면 몇 묶음이 되나요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X02"},{"t":"100","mis":"M2-1-u1-X09"}],"explanation":["10개씩 묶어요.","100은 10이 10개 — 10묶음이에요.","묶음 수와 구슬 수를 헷갈리지 않아요."]},{"stem":"100원은 10원짜리 동전 몇 개와 같나요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M2-1-u1-X09"},{"t":"1","mis":"M2-1-u1-X02"}],"explanation":["10원씩 세어요 — 10, 20, … 100.","10원짜리 10개면 100원이에요.","그래서 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#7','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'ox','auto','구슬을 10개씩 10묶음 모으면 구슬은 100개예요.',ARRAY['M2-1-u1-X02']::text[],true,'{"seq":7,"concept":"M2-1-u1-C1","difficulty":2,"kind":"ox","stem":"구슬을 10개씩 10묶음 모으면 구슬은 100개예요.","answer":"O","reason_options":[{"t":"10이 10개이면 100이니까","correct":true},{"t":"10묶음이니까 구슬은 10개라서","mis":"M2-1-u1-X02"}],"mis":"M2-1-u1-X02","explanation":["한 묶음에 구슬이 10개예요.","10이 10개이면 100이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"99 다음 수는 910이에요.","answer":"X","reason_options":[{"t":"99보다 1 큰 수는 100이니까","correct":true},{"t":"9 뒤에 10을 붙이면 되니까","mis":"M2-1-u1-X01"}],"explanation":["99에 1을 더하면 일의 자리가 10이 돼요.","그래서 십의 자리, 백의 자리로 차례로 넘어가 100이에요.","숫자를 이어 붙이지 않아요."]},{"stem":"100은 10이 1개인 수예요.","answer":"X","reason_options":[{"t":"10이 10개 모여야 100이니까","correct":true},{"t":"100에 1이 있으니까 10이 1개라서","mis":"M2-1-u1-X02"}],"explanation":["10이 1개면 10이에요.","10이 10개 모여야 100이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#8','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'blank','auto','100은 99보다 (        )만큼 더 큰 수예요.',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":8,"concept":"M2-1-u1-C1","difficulty":2,"kind":"blank","stem":"100은 99보다 (        )만큼 더 큰 수예요.","options":[{"t":"1","correct":true},{"t":"10","mis":"M2-1-u1-X12"},{"t":"100","mis":"M2-1-u1-X12"}],"explanation":["99 바로 다음 수가 100이에요.","바로 다음 수는 1만큼 더 큰 수예요.","그래서 빈칸은 1이에요."],"variant_rule":{"alt":[{"stem":"100은 90보다 (        )만큼 더 큰 수예요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X12"},{"t":"9","mis":"M2-1-u1-X12"}],"explanation":["90 다음 10씩 뛰면 100이에요.","그래서 10만큼 커요.","십 모형 1개 차이예요."]},{"stem":"10이 (        )개이면 100이에요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X02"},{"t":"100","mis":"M2-1-u1-X09"}],"explanation":["10씩 세어 100까지 가요.","10번 세면 100이에요.","10이 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#9','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',2,'match','auto','같은 수끼리 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u1-C1","difficulty":2,"kind":"match","stem":"같은 수끼리 이어 보세요.","pairs":[{"l":"99보다 1 큰 수","r":"100"},{"l":"90보다 1 큰 수","r":"91"},{"l":"10이 9개인 수","r":"90"}],"mis":"M2-1-u1-X12","explanation":["99보다 1 큰 수는 100이에요.","90보다 1 큰 수는 91, 10이 9개인 수는 90이에요.","1만큼과 10만큼을 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"90보다 10 큰 수","r":"100"},{"l":"80보다 10 큰 수","r":"90"},{"l":"99보다 1 작은 수","r":"98"}],"explanation":["90보다 10 큰 수는 100이에요.","80보다 10 큰 수는 90, 99보다 1 작은 수는 98이에요.","얼마만큼 큰지, 작은지 잘 읽어요."]},{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"10이 10개","r":"100"},{"l":"10이 8개","r":"80"},{"l":"10이 1개","r":"10"}],"explanation":["10이 10개이면 100이에요.","10이 8개면 80, 1개면 10이에요.","10이 몇 개인지로 수를 알아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_basic#10','math',2,1,'u1','L02','g2_1_math_u1_L02_basic','lesson_basic','M2-1-u1-C1',3,'sa','auto','60부터 10씩 뛰어 세었어요. 몇 번 뛰어 세면 100이 되나요?','{}'::text[],true,'{"seq":10,"concept":"M2-1-u1-C1","difficulty":3,"kind":"sa","stem":"60부터 10씩 뛰어 세었어요. 몇 번 뛰어 세면 100이 되나요?","answer":["4","4번"],"explanation":["60, 70, 80, 90, 100이에요.","70·80·90·100 — 4번 뛰었어요.","처음 수 60은 뛴 횟수에 넣지 않아요."],"variant_rule":{"alt":[{"stem":"70부터 10씩 뛰어 세었어요. 몇 번 뛰어 세면 100이 되나요?","answer":["3","3번"],"explanation":["70, 80, 90, 100이에요.","80·90·100 — 3번 뛰었어요.","처음 수는 뛴 횟수에 넣지 않아요."]},{"stem":"96부터 1씩 뛰어 세었어요. 몇 번 뛰어 세면 100이 되나요?","answer":["4","4번"],"explanation":["96, 97, 98, 99, 100이에요.","97·98·99·100 — 4번 뛰었어요.","처음 수는 뛴 횟수에 넣지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#1','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',2,'mc','auto','70과 어떤 수를 모으면 100이 돼요. 어떤 수는 무엇인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X12']::text[],true,'{"seq":1,"concept":"M2-1-u1-C1","difficulty":2,"kind":"mc","stem":"70과 어떤 수를 모으면 100이 돼요. 어떤 수는 무엇인가요?","options":[{"t":"30","correct":true},{"t":"3","mis":"M2-1-u1-X02"},{"t":"40","mis":"M2-1-u1-X12"}],"explanation":["70에서 10씩 뛰어 세면 80, 90, 100이에요.","10씩 3번 — 30이에요.","70과 30을 모으면 100이에요."],"variant_rule":{"alt":[{"stem":"40과 어떤 수를 모으면 100이 돼요. 어떤 수는 무엇인가요?","options":[{"t":"60","correct":true},{"t":"6","mis":"M2-1-u1-X02"},{"t":"50","mis":"M2-1-u1-X12"}],"explanation":["40에서 10씩 뛰면 50, 60, … 100이에요.","10씩 6번 — 60이에요.","40과 60을 모으면 100이에요."]},{"stem":"100을 똑같은 두 수로 가르면 한 수는 얼마인가요?","options":[{"t":"50","correct":true},{"t":"5","mis":"M2-1-u1-X02"},{"t":"10","mis":"M2-1-u1-X12"}],"explanation":["50과 50을 모으면 100이에요.","그래서 한 수는 50이에요.","십 모형 10개를 5개씩 나눈 것과 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#2','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',2,'error','auto','친구들이 100에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X01','M2-1-u1-X12']::text[],true,'{"seq":2,"concept":"M2-1-u1-C1","difficulty":2,"kind":"error","stem":"친구들이 100에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호: 10이 10개니까 1010이라고 써.","correct":true,"mis_target":"M2-1-u1-X02"},{"t":"하린: 99보다 1 큰 수가 100이야.","mis":"M2-1-u1-X01"},{"t":"도윤: 100은 90보다 10 큰 수야.","mis":"M2-1-u1-X12"}],"explanation":["10이 10개 모이면 새로운 자리, 백의 자리가 생겨요.","그래서 1010이 아니라 100이라고 써요.","지호가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 100에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 100은 「일영영」이라고 읽어.","correct":true,"mis_target":"M2-1-u1-X07"},{"t":"준우: 100은 「백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"라희: 100은 99 다음 수야.","mis":"M2-1-u1-X01"}],"explanation":["100은 「백」이라고 읽어요.","숫자를 하나씩 따로 읽지 않아요.","서아가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#3','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'mc','auto','구슬이 10개씩 묶음 9개와 낱개 10개 있어요. 구슬은 모두 몇 개인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":3,"concept":"M2-1-u1-C1","difficulty":3,"kind":"mc","stem":"구슬이 10개씩 묶음 9개와 낱개 10개 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X10"},{"t":"91","mis":"M2-1-u1-X10"}],"explanation":["낱개 10개는 10개씩 묶음 1개로 바꿀 수 있어요.","그러면 10개씩 묶음이 10개 — 100이에요.","낱개가 10개면 묶음 하나로 바꿔 세요."],"variant_rule":{"alt":[{"stem":"10원짜리 동전 9개와 1원짜리 동전 10개는 모두 얼마인가요?","options":[{"t":"100원","correct":true},{"t":"910원","mis":"M2-1-u1-X10"},{"t":"91원","mis":"M2-1-u1-X10"}],"explanation":["1원짜리 10개는 10원짜리 1개와 같아요.","그러면 10원짜리가 10개 — 100원이에요.","한 자리에 10개가 모이면 윗자리로 바꿔요."]},{"stem":"10개씩 묶음 8개와 낱개 20개는 모두 몇 개인가요?","options":[{"t":"100","correct":true},{"t":"820","mis":"M2-1-u1-X10"},{"t":"82","mis":"M2-1-u1-X10"}],"explanation":["낱개 20개는 10개씩 묶음 2개예요.","묶음이 8개와 2개 — 10개이니 100이에요.","낱개가 10개 넘으면 묶음으로 바꿔 세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#4','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'sa','auto','사탕 100개를 한 봉지에 10개씩 담으면 몇 봉지가 되나요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u1-C1","difficulty":3,"kind":"sa","stem":"사탕 100개를 한 봉지에 10개씩 담으면 몇 봉지가 되나요?","answer":["10","10봉지"],"explanation":["100은 10이 10개예요.","그래서 10개씩 담으면 10봉지예요.","봉지 하나에 10개 — 10, 20, … 100으로 세어 보세요."],"variant_rule":{"alt":[{"stem":"색종이 100장을 10장씩 나누어 주면 몇 명에게 줄 수 있나요?","answer":["10","10명"],"explanation":["100은 10이 10개예요.","10장씩이면 10명에게 줄 수 있어요.","10씩 세어 100이 될 때까지 세어요."]},{"stem":"10원짜리 동전으로 100원을 만들려면 몇 개가 있어야 하나요?","answer":["10","10개"],"explanation":["10원씩 세어요.","10원짜리 10개면 100원이에요.","그래서 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#5','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'ox','auto','99 다음 수는 910이에요.',ARRAY['M2-1-u1-X01']::text[],true,'{"seq":5,"concept":"M2-1-u1-C1","difficulty":3,"kind":"ox","stem":"99 다음 수는 910이에요.","answer":"X","reason_options":[{"t":"99보다 1 큰 수는 100이니까","correct":true},{"t":"9 다음에 10을 붙이면 되니까","mis":"M2-1-u1-X01"}],"mis":"M2-1-u1-X01","explanation":["99에 1을 더하면 일의 자리가 10이 돼요.","10은 윗자리로 넘어가 다시 10이 되고, 결국 100이에요.","숫자를 이어 붙이지 않아요."],"variant_rule":{"alt":[{"stem":"90 다음에 10씩 뛰어 센 수는 100이에요.","answer":"O","reason_options":[{"t":"90보다 10 큰 수는 100이니까","correct":true},{"t":"90 다음은 910이니까","mis":"M2-1-u1-X01"}],"explanation":["90에서 10을 더 뛰어요.","십 모형이 10개가 되어 100이에요.","그래서 맞는 말이에요."]},{"stem":"100은 98보다 1 큰 수예요.","answer":"X","reason_options":[{"t":"98 다음은 99, 그다음이 100이라 2 크니까","correct":true},{"t":"100은 98 바로 다음 수니까","mis":"M2-1-u1-X12"}],"explanation":["98, 99, 100이에요.","100은 98보다 2 커요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#6','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'mc','auto','10씩 뛰어 세었어요. 70, 80, 90 다음에 오는 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X12']::text[],true,'{"seq":6,"concept":"M2-1-u1-C1","difficulty":3,"kind":"mc","stem":"10씩 뛰어 세었어요. 70, 80, 90 다음에 오는 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X01"},{"t":"91","mis":"M2-1-u1-X12"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","90에서 10을 더 뛰면 십 모형이 10개 — 100이에요.","9 다음에 10을 붙여 910으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"1씩 뛰어 세었어요. 97, 98, 99 다음에 오는 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X01"},{"t":"109","mis":"M2-1-u1-X12"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","99 다음은 100이에요.","숫자를 이어 붙이지 않아요."]},{"stem":"10씩 거꾸로 뛰어 세었어요. 100 다음에 오는 수는 무엇인가요?","options":[{"t":"90","correct":true},{"t":"99","mis":"M2-1-u1-X12"},{"t":"0","mis":"M2-1-u1-X12"}],"explanation":["10씩 거꾸로 뛰면 10만큼씩 작아져요.","100보다 10 작은 수는 90이에요.","1만큼 작은 99와 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#7','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',3,'mc','auto','100이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X12']::text[],true,'{"seq":7,"concept":"M2-1-u1-C1","difficulty":3,"kind":"mc","stem":"100이 아닌 것은 어느 것인가요?","options":[{"t":"99보다 1 작은 수","correct":true},{"t":"10이 10개인 수","mis":"M2-1-u1-X02"},{"t":"90보다 10 큰 수","mis":"M2-1-u1-X12"}],"explanation":["10이 10개인 수, 90보다 10 큰 수는 모두 100이에요.","99보다 1 작은 수는 98이에요.","얼마만큼 「큰」지 「작은」지 잘 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 100이 아닌 것은 어느 것인가요?","options":[{"t":"10이 9개인 수","correct":true},{"t":"99보다 1 큰 수","mis":"M2-1-u1-X01"},{"t":"80보다 20 큰 수","mis":"M2-1-u1-X12"}],"explanation":["99보다 1 큰 수, 80보다 20 큰 수는 100이에요.","10이 9개인 수는 90이에요.","10이 10개여야 100이에요."]},{"stem":"이번에는 다른 보기예요. 100이 아닌 것은 어느 것인가요?","options":[{"t":"90보다 1 큰 수","correct":true},{"t":"50과 50을 모은 수","mis":"M2-1-u1-X02"},{"t":"10이 10개인 수","mis":"M2-1-u1-X02"}],"explanation":["50과 50을 모으면 100, 10이 10개도 100이에요.","90보다 1 큰 수는 91이에요.","90보다 「10」 커야 100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#8','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',4,'mc','auto','어떤 수보다 10만큼 더 큰 수가 100이에요. 어떤 수보다 1만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X15','M2-1-u1-X12']::text[],true,'{"seq":8,"concept":"M2-1-u1-C1","difficulty":4,"kind":"mc","stem":"어떤 수보다 10만큼 더 큰 수가 100이에요. 어떤 수보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"91","correct":true},{"t":"101","mis":"M2-1-u1-X15"},{"t":"99","mis":"M2-1-u1-X12"}],"explanation":["100보다 10 작은 수가 어떤 수예요 — 90이에요.","90보다 1 큰 수는 91이에요.","먼저 어떤 수를 찾고 나서 묻는 말을 풀어요."],"variant_rule":{"alt":[{"stem":"어떤 수보다 1만큼 더 큰 수가 100이에요. 어떤 수보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"109","correct":true},{"t":"110","mis":"M2-1-u1-X15"},{"t":"100","mis":"M2-1-u1-X12"}],"explanation":["100보다 1 작은 수가 어떤 수예요 — 99예요.","99보다 10 큰 수는 109예요.","먼저 어떤 수를 찾고 나서 묻는 말을 풀어요."]},{"stem":"어떤 수보다 20만큼 더 큰 수가 100이에요. 어떤 수보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"90","correct":true},{"t":"110","mis":"M2-1-u1-X15"},{"t":"80","mis":"M2-1-u1-X12"}],"explanation":["100보다 20 작은 수가 어떤 수예요 — 80이에요.","80보다 10 큰 수는 90이에요.","먼저 어떤 수를 찾고 나서 묻는 말을 풀어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#9','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C7',4,'sa','auto','10원짜리 동전 7개와 1원짜리 동전 30개가 있어요. 모두 얼마인가요?','{}'::text[],true,'{"seq":9,"concept":"M2-1-u1-C7","difficulty":4,"kind":"sa","stem":"10원짜리 동전 7개와 1원짜리 동전 30개가 있어요. 모두 얼마인가요?","answer":["100","100원"],"explanation":["1원짜리 30개는 10원짜리 3개와 같아요.","10원짜리가 7개와 3개 — 10개이니 100원이에요.","10개씩 모이면 윗자리로 바꿔 세요."],"variant_rule":{"alt":[{"stem":"10원짜리 동전 6개와 1원짜리 동전 40개가 있어요. 모두 얼마인가요?","answer":["100","100원"],"explanation":["1원짜리 40개는 10원짜리 4개와 같아요.","10원짜리가 6개와 4개 — 10개이니 100원이에요.","10개씩 모이면 윗자리로 바꿔 세요."]},{"stem":"10원짜리 동전 5개와 1원짜리 동전 50개가 있어요. 모두 얼마인가요?","answer":["100","100원"],"explanation":["1원짜리 50개는 10원짜리 5개와 같아요.","10원짜리가 10개 — 100원이에요.","10개씩 모이면 윗자리로 바꿔 세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L02_challenge#10','math',2,1,'u1','L02','g2_1_math_u1_L02_challenge','lesson_challenge','M2-1-u1-C1',4,'essay','teacher','100을 서로 다른 방법으로 두 가지 설명해 보세요. (예: ○○보다 ○만큼 더 큰 수)','{}'::text[],false,'{"seq":10,"concept":"M2-1-u1-C1","difficulty":4,"kind":"essay","stem":"100을 서로 다른 방법으로 두 가지 설명해 보세요. (예: ○○보다 ○만큼 더 큰 수)","answer_guide":{"answer":"예: 99보다 1 큰 수, 90보다 10 큰 수, 10이 10개인 수 가운데 두 가지","scoring_points":["서로 다른 설명 두 가지를 썼는가","설명한 수가 정말 100인가(얼마만큼 큰지 바른가)","1만큼과 10만큼을 구별해 썼는가"]},"explanation":["100은 여러 가지로 말할 수 있어요.","99보다 1 큰 수, 90보다 10 큰 수, 10이 10개인 수 모두 100이에요.","얼마만큼인지 바르게 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#1','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',1,'mc','auto','백 모형이 4개 있어요. 모두 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":1,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"백 모형이 4개 있어요. 모두 얼마인가요?","options":[{"t":"400","correct":true},{"t":"104","mis":"M2-1-u1-X03"},{"t":"40","mis":"M2-1-u1-X03"}],"explanation":["백 모형 하나는 100이에요.","100이 4개이면 400이에요.","개수 4는 백의 자리에 써요."],"asset":{"type":"blocks3","h":4,"t":0,"o":0},"variant_rule":{"alt":[{"stem":"백 모형이 6개 있어요. 모두 얼마인가요?","options":[{"t":"600","correct":true},{"t":"106","mis":"M2-1-u1-X03"},{"t":"60","mis":"M2-1-u1-X03"}],"explanation":["백 모형 하나는 100이에요.","100이 6개이면 600이에요.","개수 6은 백의 자리에 써요."],"asset":{"type":"blocks3","h":6,"t":0,"o":0}},{"stem":"백 모형이 3개 있어요. 모두 얼마인가요?","options":[{"t":"300","correct":true},{"t":"103","mis":"M2-1-u1-X03"},{"t":"30","mis":"M2-1-u1-X03"}],"explanation":["백 모형 하나는 100이에요.","100이 3개이면 300이에요.","개수 3은 백의 자리에 써요."],"asset":{"type":"blocks3","h":3,"t":0,"o":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#2','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',1,'mc','auto','100이 5개이면 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":2,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"100이 5개이면 얼마인가요?","options":[{"t":"500","correct":true},{"t":"105","mis":"M2-1-u1-X03"},{"t":"50","mis":"M2-1-u1-X03"}],"explanation":["100이 5개이면 500이에요.","「오백」이라고 읽어요.","개수는 백의 자리에 쓰고, 십·일의 자리는 0이에요."],"variant_rule":{"n3":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#3','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',1,'mc','auto','700을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u1-X07','M2-1-u1-X03']::text[],true,'{"seq":3,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"700을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"칠백","correct":true},{"t":"칠영영","mis":"M2-1-u1-X07"},{"t":"칠십","mis":"M2-1-u1-X03"}],"explanation":["700은 100이 7개예요.","「칠백」이라고 읽어요.","0인 자리는 읽지 않아요."],"variant_rule":{"alt":[{"stem":"300을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"삼백","correct":true},{"t":"삼영영","mis":"M2-1-u1-X07"},{"t":"삼십","mis":"M2-1-u1-X03"}],"explanation":["300은 100이 3개예요.","「삼백」이라고 읽어요.","0인 자리는 읽지 않아요."]},{"stem":"「구백」을 수로 쓰면 무엇인가요?","options":[{"t":"900","correct":true},{"t":"9100","mis":"M2-1-u1-X05"},{"t":"90","mis":"M2-1-u1-X03"}],"explanation":["「구백」은 100이 9개예요.","수로 쓰면 900이에요.","9 뒤에 0을 두 개 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#4','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',1,'sa','auto','800은 100이 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u1-C2","difficulty":1,"kind":"sa","stem":"800은 100이 몇 개인가요?","answer":["8","8개"],"explanation":["800은 백의 자리 숫자가 8이에요.","100이 8개예요.","백의 자리 숫자가 100의 개수예요."],"variant_rule":{"n3":{"ask":"hcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#5','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":5,"concept":"M2-1-u1-C2","difficulty":2,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"600원","correct":true},{"t":"106원","mis":"M2-1-u1-X03"},{"t":"60원","mis":"M2-1-u1-X03"}],"explanation":["100원짜리 동전 하나는 100원이에요.","100원짜리가 6개이면 600원이에요.","100씩 세어 보세요 — 100, 200, … 600."],"asset":{"type":"blocks3","h":6,"t":0,"o":0,"unit":"coin"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 동전은 모두 얼마인가요?","options":[{"t":"400원","correct":true},{"t":"104원","mis":"M2-1-u1-X03"},{"t":"40원","mis":"M2-1-u1-X03"}],"explanation":["100원짜리 동전 하나는 100원이에요.","100원짜리가 4개이면 400원이에요.","100씩 세어 보세요 — 100, 200, 300, 400."],"asset":{"type":"blocks3","h":4,"t":0,"o":0,"unit":"coin"}},{"stem":"이번에는 다른 보기예요. 동전은 모두 얼마인가요?","options":[{"t":"800원","correct":true},{"t":"108원","mis":"M2-1-u1-X03"},{"t":"80원","mis":"M2-1-u1-X03"}],"explanation":["100원짜리 동전 하나는 100원이에요.","100원짜리가 8개이면 800원이에요.","100씩 세어 보세요."],"asset":{"type":"blocks3","h":8,"t":0,"o":0,"unit":"coin"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#6','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'match','auto','같은 수끼리 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u1-C2","difficulty":2,"kind":"match","stem":"같은 수끼리 이어 보세요.","pairs":[{"l":"100이 3개","r":"300"},{"l":"이백","r":"200"},{"l":"100이 9개","r":"900"}],"mis":"M2-1-u1-X03","explanation":["100이 3개는 300, 100이 9개는 900이에요.","「이백」은 200이에요.","100의 개수는 백의 자리 숫자예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"100이 5개","r":"500"},{"l":"칠백","r":"700"},{"l":"100이 4개","r":"400"}],"explanation":["100이 5개는 500, 100이 4개는 400이에요.","「칠백」은 700이에요.","100의 개수는 백의 자리 숫자예요."]},{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"육백","r":"600"},{"l":"100이 2개","r":"200"},{"l":"팔백","r":"800"}],"explanation":["「육백」은 600, 「팔백」은 800이에요.","100이 2개는 200이에요.","몇백은 백의 자리만 0이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#7','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'blank','auto','500은 100이 (        )개인 수예요.',ARRAY['M2-1-u1-X03','M2-1-u1-X09']::text[],true,'{"seq":7,"concept":"M2-1-u1-C2","difficulty":2,"kind":"blank","stem":"500은 100이 (        )개인 수예요.","options":[{"t":"5","correct":true},{"t":"50","mis":"M2-1-u1-X03"},{"t":"500","mis":"M2-1-u1-X09"}],"explanation":["500은 백의 자리 숫자가 5예요.","그래서 100이 5개예요.","백의 자리 숫자가 100의 개수예요."],"variant_rule":{"n3":{"ask":"hcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#8','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'ox','auto','100이 6개인 수는 106이에요.',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":8,"concept":"M2-1-u1-C2","difficulty":2,"kind":"ox","stem":"100이 6개인 수는 106이에요.","answer":"X","reason_options":[{"t":"100이 6개이면 600이니까","correct":true},{"t":"100 뒤에 6을 붙이면 되니까","mis":"M2-1-u1-X03"}],"mis":"M2-1-u1-X03","explanation":["100씩 6번 세면 100, 200, … 600이에요.","100이 6개인 수는 600이에요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"400은 100이 4개인 수예요.","answer":"O","reason_options":[{"t":"100씩 4번 세면 400이니까","correct":true},{"t":"400은 10이 4개라서","mis":"M2-1-u1-X03"}],"explanation":["100, 200, 300, 400이에요.","400은 100이 4개예요.","그래서 맞는 말이에요."]},{"stem":"100이 3개인 수는 30이에요.","answer":"X","reason_options":[{"t":"100이 3개이면 300이니까","correct":true},{"t":"개수 3 뒤에 0을 하나 붙이면 되니까","mis":"M2-1-u1-X03"}],"explanation":["100씩 3번 — 100, 200, 300이에요.","100이 3개인 수는 300이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#9','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',2,'mc','auto','300보다 100만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":9,"concept":"M2-1-u1-C2","difficulty":2,"kind":"mc","stem":"300보다 100만큼 더 큰 수는 무엇인가요?","options":[{"t":"400","correct":true},{"t":"310","mis":"M2-1-u1-X12"},{"t":"301","mis":"M2-1-u1-X12"}],"explanation":["100만큼 더 크면 백의 자리 숫자가 1 커져요.","300보다 100 큰 수는 400이에요.","10만큼·1만큼과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"700보다 100만큼 더 작은 수는 무엇인가요?","options":[{"t":"600","correct":true},{"t":"690","mis":"M2-1-u1-X12"},{"t":"800","mis":"M2-1-u1-X12"}],"explanation":["100만큼 작으면 백의 자리 숫자가 1 작아져요.","700보다 100 작은 수는 600이에요.","「작은」인지 「큰」인지 잘 읽어요."]},{"stem":"500보다 100만큼 더 큰 수는 무엇인가요?","options":[{"t":"600","correct":true},{"t":"510","mis":"M2-1-u1-X12"},{"t":"501","mis":"M2-1-u1-X12"}],"explanation":["100만큼 더 크면 백의 자리 숫자가 1 커져요.","500보다 100 큰 수는 600이에요.","10만큼·1만큼과 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_basic#10','math',2,1,'u1','L03','g2_1_math_u1_L03_basic','lesson_basic','M2-1-u1-C2',3,'mc','auto','100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":10,"concept":"M2-1-u1-C2","difficulty":3,"kind":"mc","stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"700","correct":true},{"t":"610","mis":"M2-1-u1-X11"},{"t":"601","mis":"M2-1-u1-X11"}],"explanation":["100씩 뛰면 백의 자리 숫자가 1씩 커져요.","600에서 100만큼 뛰면 700이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[300,400,500,600,null],"step":100},"variant_rule":{"skip3":{"ask":"next","step":[100]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#1','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C7',2,'mc','auto','340은 10이 몇 개인가요?',ARRAY['M2-1-u1-X10','M2-1-u1-X03']::text[],true,'{"seq":1,"concept":"M2-1-u1-C7","difficulty":2,"kind":"mc","stem":"340은 10이 몇 개인가요?","options":[{"t":"34","correct":true},{"t":"4","mis":"M2-1-u1-X10"},{"t":"3","mis":"M2-1-u1-X03"}],"explanation":["340은 100이 3개, 10이 4개예요.","100 하나는 10이 10개 — 10이 30개와 4개, 모두 34개예요.","100 속에도 10이 10개 들어 있어요."],"variant_rule":{"n3":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#2','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',2,'error','auto','친구들이 600에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u1-X03','M2-1-u1-X07','M2-1-u1-X12']::text[],true,'{"seq":2,"concept":"M2-1-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 600에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우: 600은 100이 60개야.","correct":true,"mis_target":"M2-1-u1-X03"},{"t":"하린: 600은 「육백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"도윤: 600은 500보다 100 큰 수야.","mis":"M2-1-u1-X12"}],"explanation":["600은 백의 자리 숫자가 6이에요.","그래서 100이 6개예요 — 60개가 아니에요.","은우가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"친구들이 300에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온: 300은 100이 3개니까 103이라고 써.","correct":true,"mis_target":"M2-1-u1-X03"},{"t":"서준: 300은 「삼백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"지아: 300은 200보다 100 큰 수야.","mis":"M2-1-u1-X12"}],"explanation":["100이 3개이면 300이에요.","개수를 일의 자리에 붙여 103으로 쓰지 않아요.","라온이 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#3','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C7',3,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":3,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"400원","correct":true},{"t":"3100원","mis":"M2-1-u1-X10"},{"t":"310원","mis":"M2-1-u1-X10"}],"explanation":["10원짜리 10개는 100원짜리 1개와 같아요.","100원짜리가 3개와 1개 — 400원이에요.","한 자리에 10개가 모이면 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":3,"t":10,"o":0,"unit":"coin"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 동전은 모두 얼마인가요?","options":[{"t":"600원","correct":true},{"t":"5100원","mis":"M2-1-u1-X10"},{"t":"510원","mis":"M2-1-u1-X10"}],"explanation":["10원짜리 10개는 100원짜리 1개와 같아요.","100원짜리가 5개와 1개 — 600원이에요.","한 자리에 10개가 모이면 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":5,"t":10,"o":0,"unit":"coin"}},{"stem":"이번에는 다른 보기예요. 동전은 모두 얼마인가요?","options":[{"t":"290원","correct":true},{"t":"1190원","mis":"M2-1-u1-X10"},{"t":"190원","mis":"M2-1-u1-X10"}],"explanation":["10원짜리 19개는 100원짜리 1개와 10원짜리 9개로 바꿀 수 있어요.","100원짜리가 2개, 10원짜리가 9개 — 290원이에요.","10개씩 묶어 윗자리로 바꿔요."],"asset":{"type":"blocks3","h":1,"t":19,"o":0,"unit":"coin"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#4','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',3,'sa','auto','공책이 한 상자에 100권씩 들어 있어요. 7상자에는 공책이 모두 몇 권인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u1-C2","difficulty":3,"kind":"sa","stem":"공책이 한 상자에 100권씩 들어 있어요. 7상자에는 공책이 모두 몇 권인가요?","answer":["700","700권"],"explanation":["한 상자에 100권씩이에요.","100이 7개이면 700이에요.","100씩 세어 보세요 — 100, 200, … 700."],"variant_rule":{"alt":[{"stem":"귤이 한 상자에 100개씩 들어 있어요. 4상자에는 귤이 모두 몇 개인가요?","answer":["400","400개"],"explanation":["한 상자에 100개씩이에요.","100이 4개이면 400이에요.","100씩 세어 보세요."]},{"stem":"색종이가 한 묶음에 100장씩 있어요. 9묶음은 모두 몇 장인가요?","answer":["900","900장"],"explanation":["한 묶음에 100장씩이에요.","100이 9개이면 900이에요.","100씩 세어 보세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#5','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C7',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":5,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"300","correct":true},{"t":"2100","mis":"M2-1-u1-X10"},{"t":"210","mis":"M2-1-u1-X10"}],"explanation":["십 모형 10개는 백 모형 1개와 같아요.","백 모형이 2개와 1개 — 300이에요.","한 자리에 10개가 모이면 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":2,"t":10,"o":0},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#6','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',3,'mc','auto','800은 400보다 100이 몇 개 더 많은가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X03']::text[],true,'{"seq":6,"concept":"M2-1-u1-C2","difficulty":3,"kind":"mc","stem":"800은 400보다 100이 몇 개 더 많은가요?","options":[{"t":"4","correct":true},{"t":"400","mis":"M2-1-u1-X09"},{"t":"40","mis":"M2-1-u1-X03"}],"explanation":["800은 100이 8개, 400은 100이 4개예요.","8은 4보다 4 커요.","그래서 100이 4개 더 많아요."],"variant_rule":{"alt":[{"stem":"900은 600보다 100이 몇 개 더 많은가요?","options":[{"t":"3","correct":true},{"t":"300","mis":"M2-1-u1-X09"},{"t":"30","mis":"M2-1-u1-X03"}],"explanation":["900은 100이 9개, 600은 100이 6개예요.","9는 6보다 3 커요.","그래서 100이 3개 더 많아요."]},{"stem":"700은 200보다 100이 몇 개 더 많은가요?","options":[{"t":"5","correct":true},{"t":"500","mis":"M2-1-u1-X09"},{"t":"50","mis":"M2-1-u1-X03"}],"explanation":["700은 100이 7개, 200은 100이 2개예요.","7은 2보다 5 커요.","그래서 100이 5개 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#7','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',3,'ox','auto','100이 10개이면 1000이에요.',ARRAY['M2-1-u1-X02']::text[],true,'{"seq":7,"concept":"M2-1-u1-C2","difficulty":3,"kind":"ox","stem":"100이 10개이면 1000이에요.","answer":"O","reason_options":[{"t":"100이 10개 모이면 천이 되니까","correct":true},{"t":"100이 10개면 10010이니까","mis":"M2-1-u1-X02"}],"mis":"M2-1-u1-X02","explanation":["100씩 10번 세면 100, 200, … 900, 1000이에요.","100이 10개이면 1000(천)이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"900보다 100 큰 수는 9100이에요.","answer":"X","reason_options":[{"t":"900보다 100 큰 수는 1000이니까","correct":true},{"t":"9 다음에 100을 붙이면 되니까","mis":"M2-1-u1-X01"}],"explanation":["100이 9개에 1개를 더하면 10개예요.","100이 10개이면 1000이에요.","숫자를 이어 붙이지 않아요."]},{"stem":"1000은 100이 10개인 수예요.","answer":"O","reason_options":[{"t":"100씩 10번 세면 1000이니까","correct":true},{"t":"1000은 100이 1개라서","mis":"M2-1-u1-X02"}],"explanation":["100, 200, … 1000 — 10번이에요.","1000은 100이 10개예요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#8','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',4,'mc','auto','어떤 수는 100이 4개인 수보다 100이 3개 더 많아요. 어떤 수는 무엇인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":8,"concept":"M2-1-u1-C2","difficulty":4,"kind":"mc","stem":"어떤 수는 100이 4개인 수보다 100이 3개 더 많아요. 어떤 수는 무엇인가요?","options":[{"t":"700","correct":true},{"t":"430","mis":"M2-1-u1-X03"},{"t":"403","mis":"M2-1-u1-X03"}],"explanation":["100이 4개에 3개가 더 많으면 100이 7개예요.","100이 7개인 수는 700이에요.","100의 개수는 모두 백의 자리에 모여요."],"variant_rule":{"alt":[{"stem":"어떤 수는 100이 8개인 수보다 100이 2개 더 적어요. 어떤 수는 무엇인가요?","options":[{"t":"600","correct":true},{"t":"820","mis":"M2-1-u1-X03"},{"t":"1000","mis":"M2-1-u1-X15"}],"explanation":["100이 8개에서 2개가 적으면 100이 6개예요.","100이 6개인 수는 600이에요.","「적어요」를 잘 읽어요."]},{"stem":"어떤 수는 100이 2개인 수보다 100이 5개 더 많아요. 어떤 수는 무엇인가요?","options":[{"t":"700","correct":true},{"t":"250","mis":"M2-1-u1-X03"},{"t":"205","mis":"M2-1-u1-X03"}],"explanation":["100이 2개에 5개가 더 많으면 100이 7개예요.","100이 7개인 수는 700이에요.","100의 개수는 모두 백의 자리에 모여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#9','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C2',4,'mc','auto','100원짜리 동전으로 900원을 내려고 해요. 지금 100원짜리가 5개 있다면 몇 개가 더 있어야 하나요?',ARRAY['M2-1-u1-X09','M2-1-u1-X15']::text[],true,'{"seq":9,"concept":"M2-1-u1-C2","difficulty":4,"kind":"mc","stem":"100원짜리 동전으로 900원을 내려고 해요. 지금 100원짜리가 5개 있다면 몇 개가 더 있어야 하나요?","options":[{"t":"4","correct":true},{"t":"400","mis":"M2-1-u1-X09"},{"t":"9","mis":"M2-1-u1-X15"}],"explanation":["900원은 100원짜리 9개예요.","5개가 있으니 9개가 되려면 4개 더 — 6, 7, 8, 9로 세어요.","묻는 것은 동전 「개수」예요."],"variant_rule":{"alt":[{"stem":"100원짜리 동전으로 800원을 내려고 해요. 지금 100원짜리가 3개 있다면 몇 개가 더 있어야 하나요?","options":[{"t":"5","correct":true},{"t":"500","mis":"M2-1-u1-X09"},{"t":"8","mis":"M2-1-u1-X15"}],"explanation":["800원은 100원짜리 8개예요.","3개가 있으니 5개 더 있어야 해요.","묻는 것은 동전 「개수」예요."]},{"stem":"100원짜리 동전으로 700원을 내려고 해요. 지금 100원짜리가 6개 있다면 몇 개가 더 있어야 하나요?","options":[{"t":"1","correct":true},{"t":"100","mis":"M2-1-u1-X09"},{"t":"7","mis":"M2-1-u1-X15"}],"explanation":["700원은 100원짜리 7개예요.","6개가 있으니 1개 더 있어야 해요.","묻는 것은 동전 「개수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L03_challenge#10','math',2,1,'u1','L03','g2_1_math_u1_L03_challenge','lesson_challenge','M2-1-u1-C7',4,'essay','teacher','500을 「100이 몇 개」와 「10이 몇 개」 두 가지로 나타내고, 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u1-C7","difficulty":4,"kind":"essay","stem":"500을 「100이 몇 개」와 「10이 몇 개」 두 가지로 나타내고, 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"100이 5개, 10이 50개. 100 하나는 10이 10개이므로 100이 5개는 10이 50개이다.","scoring_points":["100이 5개라고 썼는가","10이 50개라고 썼는가","100 하나가 10이 10개라는 까닭을 말했는가"]},"explanation":["500은 백의 자리 숫자가 5 — 100이 5개예요.","100 하나는 10이 10개이니 10이 50개예요.","한 수를 여러 묶음으로 나타낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#1','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X06','M2-1-u1-X05']::text[],true,'{"seq":1,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"254","correct":true},{"t":"452","mis":"M2-1-u1-X06"},{"t":"200504","mis":"M2-1-u1-X05"}],"explanation":["100이 2개, 10이 5개, 1이 4개예요.","백의 자리 2, 십의 자리 5, 일의 자리 4 — 254예요.","백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks3","h":2,"t":5,"o":4},"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#2','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',1,'sa','auto','100이 3개, 10이 4개, 1이 7개인 수는 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u1-C3","difficulty":1,"kind":"sa","stem":"100이 3개, 10이 4개, 1이 7개인 수는 무엇인가요?","answer":["347"],"explanation":["100이 3개, 10이 4개, 1이 7개예요.","백의 자리 3, 십의 자리 4, 일의 자리 7 — 347이에요.","백·십·일 차례로 숫자를 써요."],"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#3','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',1,'mc','auto','254를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u1-X07']::text[],true,'{"seq":3,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"254를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"이백오십사","correct":true},{"t":"이오사","mis":"M2-1-u1-X07"},{"t":"이백오사","mis":"M2-1-u1-X07"}],"explanation":["254는 백의 자리 2, 십의 자리 5, 일의 자리 4예요.","「이백오십사」라고 읽어요.","숫자 뒤에 자리 이름(백·십)을 붙여 읽어요."],"variant_rule":{"n3":{"ask":"read"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#4','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',1,'mc','auto','「육백삼십오」를 수로 쓰면 무엇인가요?',ARRAY['M2-1-u1-X05','M2-1-u1-X06']::text[],true,'{"seq":4,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"「육백삼십오」를 수로 쓰면 무엇인가요?","options":[{"t":"635","correct":true},{"t":"600305","mis":"M2-1-u1-X05"},{"t":"536","mis":"M2-1-u1-X06"}],"explanation":["「육백삼십오」는 100이 6개, 10이 3개, 1이 5개예요.","수로 쓰면 635예요.","읽은 소리를 그대로 이어 쓰지 않아요 — 세 자리에 숫자 하나씩."],"variant_rule":{"n3":{"ask":"write"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#5','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'mc','auto','100이 5개, 1이 3개인 수는 무엇인가요?',ARRAY['M2-1-u1-X04','M2-1-u1-X05']::text[],true,'{"seq":5,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"100이 5개, 1이 3개인 수는 무엇인가요?","options":[{"t":"503","correct":true},{"t":"53","mis":"M2-1-u1-X04"},{"t":"5003","mis":"M2-1-u1-X05"}],"explanation":["100이 5개, 1이 3개예요 — 10은 없어요.","백의 자리 5, 십의 자리 0, 일의 자리 3 — 503이에요.","없는 자리에는 0을 써서 자리를 지켜요."],"variant_rule":{"n3":{"ask":"build","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#6','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'mc','auto','507을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u1-X07']::text[],true,'{"seq":6,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"507을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"오백칠","correct":true},{"t":"오백영칠","mis":"M2-1-u1-X07"},{"t":"오영칠","mis":"M2-1-u1-X07"}],"explanation":["507은 백의 자리 5, 십의 자리 0, 일의 자리 7이에요.","「오백칠」이라고 읽어요.","0이 있는 자리는 읽지 않아요."],"variant_rule":{"n3":{"ask":"read","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#7','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X06']::text[],true,'{"seq":7,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"236원","correct":true},{"t":"632원","mis":"M2-1-u1-X06"},{"t":"326원","mis":"M2-1-u1-X06"}],"explanation":["100원짜리가 2개, 10원짜리가 3개, 1원짜리가 6개예요.","백의 자리 2, 십의 자리 3, 일의 자리 6 — 236원이에요.","큰 동전부터 차례로 세어요."],"asset":{"type":"blocks3","h":2,"t":3,"o":6,"unit":"coin"},"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#8','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'ox','auto','「구백이」를 수로 쓰면 92예요.',ARRAY['M2-1-u1-X04']::text[],true,'{"seq":8,"concept":"M2-1-u1-C3","difficulty":2,"kind":"ox","stem":"「구백이」를 수로 쓰면 92예요.","answer":"X","reason_options":[{"t":"십의 자리에 0을 써서 902이니까","correct":true},{"t":"읽은 숫자만 쓰면 되니까","mis":"M2-1-u1-X04"}],"mis":"M2-1-u1-X04","explanation":["「구백이」는 100이 9개, 1이 2개예요.","십의 자리에 0을 써서 902예요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"「삼백사십」을 수로 쓰면 340이에요.","answer":"O","reason_options":[{"t":"일의 자리에 0을 써서 340이니까","correct":true},{"t":"읽지 않은 자리는 쓰지 않으니까 34라서","mis":"M2-1-u1-X04"}],"explanation":["「삼백사십」은 100이 3개, 10이 4개예요.","일의 자리에 0을 써서 340이에요.","그래서 맞는 말이에요."]},{"stem":"「육백팔」을 수로 쓰면 6008이에요.","answer":"X","reason_options":[{"t":"세 자리 수는 숫자가 세 개라 608이니까","correct":true},{"t":"육백은 600, 팔은 8이라 이어 쓰니까","mis":"M2-1-u1-X05"}],"explanation":["「육백팔」은 100이 6개, 1이 8개예요.","십의 자리에 0을 써서 608이에요.","읽은 소리를 이어 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#9','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C3',2,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u1-C3","difficulty":2,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"346","r":"삼백사십육"},{"l":"306","r":"삼백육"},{"l":"360","r":"삼백육십"}],"mis":"M2-1-u1-X04","explanation":["346은 삼백사십육, 306은 삼백육이에요.","360은 삼백육십이에요.","0인 자리는 읽지 않아요 — 어느 자리가 0인지 잘 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"815","r":"팔백십오"},{"l":"805","r":"팔백오"},{"l":"850","r":"팔백오십"}],"explanation":["815는 팔백십오, 805는 팔백오예요.","850은 팔백오십이에요.","0인 자리는 읽지 않아요."]},{"stem":"이번에는 다른 보기예요. 수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"472","r":"사백칠십이"},{"l":"427","r":"사백이십칠"},{"l":"742","r":"칠백사십이"}],"explanation":["472는 사백칠십이, 427은 사백이십칠이에요.","742는 칠백사십이예요.","자리 순서를 섞지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_basic#10','math',2,1,'u1','L04','g2_1_math_u1_L04_basic','lesson_basic','M2-1-u1-C7',3,'mc','auto','구슬이 100개씩 2상자, 10개씩 4봉지, 낱개 13개 있어요. 구슬은 모두 몇 개인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":10,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"구슬이 100개씩 2상자, 10개씩 4봉지, 낱개 13개 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"253","correct":true},{"t":"2413","mis":"M2-1-u1-X10"},{"t":"243","mis":"M2-1-u1-X10"}],"explanation":["낱개 13개는 10개씩 1봉지와 낱개 3개로 바꿀 수 있어요.","그러면 100이 2개, 10이 5개, 1이 3개 — 253이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."],"variant_rule":{"alt":[{"stem":"구슬이 100개씩 3상자, 10개씩 12봉지, 낱개 5개 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"425","correct":true},{"t":"3125","mis":"M2-1-u1-X10"},{"t":"325","mis":"M2-1-u1-X10"}],"explanation":["10개씩 12봉지는 100개 1상자와 10개씩 2봉지예요.","그러면 100이 4개, 10이 2개, 1이 5개 — 425예요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]},{"stem":"색종이가 100장씩 1묶음, 10장씩 6묶음, 낱장 14장 있어요. 모두 몇 장인가요?","options":[{"t":"174","correct":true},{"t":"1614","mis":"M2-1-u1-X10"},{"t":"164","mis":"M2-1-u1-X10"}],"explanation":["낱장 14장은 10장씩 1묶음과 낱장 4장이에요.","그러면 100이 1개, 10이 7개, 1이 4개 — 174예요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#1','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C3',2,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X04','M2-1-u1-X05']::text[],true,'{"seq":1,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"406","correct":true},{"t":"46","mis":"M2-1-u1-X04"},{"t":"4006","mis":"M2-1-u1-X05"}],"explanation":["100이 4개, 1이 6개예요 — 십 모형이 없어요.","백의 자리 4, 십의 자리 0, 일의 자리 6 — 406이에요.","없는 자리에는 0을 써서 자리를 지켜요."],"asset":{"type":"blocks3","h":4,"t":0,"o":6},"variant_rule":{"n3":{"ask":"build","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#2','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C3',2,'sa','auto','「칠백십」을 수로 쓰면 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u1-C3","difficulty":2,"kind":"sa","stem":"「칠백십」을 수로 쓰면 무엇인가요?","answer":["710"],"explanation":["「칠백십」은 100이 7개, 10이 1개예요.","일의 자리에 0을 써서 710이에요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n3":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#3','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C7',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":3,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"425","correct":true},{"t":"3125","mis":"M2-1-u1-X10"},{"t":"325","mis":"M2-1-u1-X10"}],"explanation":["십 모형 12개는 백 모형 1개와 십 모형 2개로 바꿀 수 있어요.","100이 4개, 10이 2개, 1이 5개 — 425예요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":3,"t":12,"o":5},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#4','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C3',3,'error','auto','친구들이 읽은 수를 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-1-u1-X04','M2-1-u1-X05']::text[],true,'{"seq":4,"concept":"M2-1-u1-C3","difficulty":3,"kind":"error","stem":"친구들이 읽은 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"서준: 「사백오」 → 45","correct":true,"mis_target":"M2-1-u1-X04"},{"t":"지아: 「사백오십」 → 450","mis":"M2-1-u1-X04"},{"t":"민재: 「사백오십오」 → 455","mis":"M2-1-u1-X05"}],"explanation":["「사백오」는 100이 4개, 1이 5개예요.","십의 자리에 0을 써서 405라고 써야 해요.","서준이가 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 읽은 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"하윤: 「이백칠십」 → 20070","correct":true,"mis_target":"M2-1-u1-X05"},{"t":"도하: 「이백칠」 → 207","mis":"M2-1-u1-X04"},{"t":"나은: 「이백칠십칠」 → 277","mis":"M2-1-u1-X06"}],"explanation":["「이백칠십」은 100이 2개, 10이 7개예요.","세 자리에 숫자 하나씩 — 270이라고 써야 해요.","하윤이가 잘못 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#5','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C7',3,'mc','auto','100이 6개, 10이 13개, 1이 2개인 수는 무엇인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":5,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"100이 6개, 10이 13개, 1이 2개인 수는 무엇인가요?","options":[{"t":"732","correct":true},{"t":"6132","mis":"M2-1-u1-X10"},{"t":"632","mis":"M2-1-u1-X10"}],"explanation":["10이 13개는 100이 1개, 10이 3개예요.","그러면 100이 7개, 10이 3개, 1이 2개 — 732예요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."],"variant_rule":{"alt":[{"stem":"100이 2개, 10이 5개, 1이 17개인 수는 무엇인가요?","options":[{"t":"267","correct":true},{"t":"2517","mis":"M2-1-u1-X10"},{"t":"257","mis":"M2-1-u1-X10"}],"explanation":["1이 17개는 10이 1개, 1이 7개예요.","그러면 100이 2개, 10이 6개, 1이 7개 — 267이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]},{"stem":"100이 4개, 10이 11개인 수는 무엇인가요?","options":[{"t":"510","correct":true},{"t":"4110","mis":"M2-1-u1-X10"},{"t":"410","mis":"M2-1-u1-X10"}],"explanation":["10이 11개는 100이 1개, 10이 1개예요.","그러면 100이 5개, 10이 1개 — 510이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#6','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C7',3,'mc','auto','10이 25개인 수는 얼마인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X10']::text[],true,'{"seq":6,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"10이 25개인 수는 얼마인가요?","options":[{"t":"250","correct":true},{"t":"1025","mis":"M2-1-u1-X02"},{"t":"25","mis":"M2-1-u1-X10"}],"explanation":["10이 10개면 100이에요.","10이 25개는 100이 2개, 10이 5개 — 250이에요.","10이 10개 넘게 모이면 100으로 바꿔 세요."],"variant_rule":{"n3":{"ask":"tens"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#7','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C3',3,'ox','auto','백 모형 3개, 일 모형 8개를 수로 쓰면 38이에요.',ARRAY['M2-1-u1-X04']::text[],true,'{"seq":7,"concept":"M2-1-u1-C3","difficulty":3,"kind":"ox","stem":"백 모형 3개, 일 모형 8개를 수로 쓰면 38이에요.","answer":"X","reason_options":[{"t":"십의 자리에 0을 써서 308이니까","correct":true},{"t":"없는 모형은 쓰지 않으니까","mis":"M2-1-u1-X04"}],"mis":"M2-1-u1-X04","explanation":["백 모형 3개, 일 모형 8개 — 십 모형은 없어요.","십의 자리에 0을 써서 308이에요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"백 모형 5개, 십 모형 2개를 수로 쓰면 520이에요.","answer":"O","reason_options":[{"t":"일의 자리에 0을 써서 520이니까","correct":true},{"t":"일 모형이 없으니 52라서","mis":"M2-1-u1-X04"}],"explanation":["백 모형 5개, 십 모형 2개 — 일 모형은 없어요.","일의 자리에 0을 써서 520이에요.","그래서 맞는 말이에요."]},{"stem":"백 모형 2개, 십 모형 4개, 일 모형 9개를 수로 쓰면 942예요.","answer":"X","reason_options":[{"t":"백·십·일 차례로 써서 249니까","correct":true},{"t":"많이 있는 모형부터 쓰니까","mis":"M2-1-u1-X06"}],"explanation":["백의 자리 2, 십의 자리 4, 일의 자리 9예요.","그래서 249예요.","자리 순서를 바꾸지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#8','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C3',4,'mc','auto','백의 자리 숫자가 4, 십의 자리 숫자가 0이고, 일의 자리 숫자는 백의 자리 숫자보다 3 큰 세 자리 수는 무엇인가요?',ARRAY['M2-1-u1-X04','M2-1-u1-X06']::text[],true,'{"seq":8,"concept":"M2-1-u1-C3","difficulty":4,"kind":"mc","stem":"백의 자리 숫자가 4, 십의 자리 숫자가 0이고, 일의 자리 숫자는 백의 자리 숫자보다 3 큰 세 자리 수는 무엇인가요?","options":[{"t":"407","correct":true},{"t":"47","mis":"M2-1-u1-X04"},{"t":"704","mis":"M2-1-u1-X06"}],"explanation":["일의 자리 숫자는 4보다 3 큰 7이에요.","백 4, 십 0, 일 7 — 407이에요.","십의 자리 0을 빠뜨리지 않아요."],"variant_rule":{"alt":[{"stem":"백의 자리 숫자가 6, 일의 자리 숫자가 0이고, 십의 자리 숫자는 백의 자리 숫자보다 2 작은 세 자리 수는 무엇인가요?","options":[{"t":"640","correct":true},{"t":"64","mis":"M2-1-u1-X04"},{"t":"604","mis":"M2-1-u1-X06"}],"explanation":["십의 자리 숫자는 6보다 2 작은 4예요.","백 6, 십 4, 일 0 — 640이에요.","일의 자리 0을 빠뜨리지 않아요."]},{"stem":"세 자리 수 가운데 백의 자리 숫자가 5이고, 십의 자리와 일의 자리 숫자가 모두 백의 자리 숫자보다 1 작은 수는 무엇인가요?","options":[{"t":"544","correct":true},{"t":"566","mis":"M2-1-u1-X15"},{"t":"454","mis":"M2-1-u1-X06"}],"explanation":["5보다 1 작은 수는 4예요.","백 5, 십 4, 일 4 — 544예요.","「작은」을 잘 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#9','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C7',4,'mc','auto','사탕이 100개씩 3봉지, 10개씩 8봉지, 낱개 25개 있어요. 사탕은 모두 몇 개인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":9,"concept":"M2-1-u1-C7","difficulty":4,"kind":"mc","stem":"사탕이 100개씩 3봉지, 10개씩 8봉지, 낱개 25개 있어요. 사탕은 모두 몇 개인가요?","options":[{"t":"405","correct":true},{"t":"3825","mis":"M2-1-u1-X10"},{"t":"385","mis":"M2-1-u1-X10"}],"explanation":["낱개 25개는 10개씩 2봉지와 낱개 5개예요.","10개씩 봉지가 8개와 2개 — 10개이니 100개 1봉지로 바꿔요.","100이 4개, 10이 0개, 1이 5개 — 405예요."],"variant_rule":{"alt":[{"stem":"딱지가 100장씩 1묶음, 10장씩 9묶음, 낱장 12장 있어요. 딱지는 모두 몇 장인가요?","options":[{"t":"202","correct":true},{"t":"1912","mis":"M2-1-u1-X10"},{"t":"192","mis":"M2-1-u1-X10"}],"explanation":["낱장 12장은 10장씩 1묶음과 낱장 2장이에요.","10장씩 묶음이 9개와 1개 — 10개이니 100장 1묶음으로 바꿔요.","100이 2개, 10이 0개, 1이 2개 — 202예요."]},{"stem":"100원짜리 2개, 10원짜리 9개, 1원짜리 15개는 모두 얼마인가요?","options":[{"t":"305원","correct":true},{"t":"2915원","mis":"M2-1-u1-X10"},{"t":"295원","mis":"M2-1-u1-X10"}],"explanation":["1원짜리 15개는 10원짜리 1개와 1원짜리 5개예요.","10원짜리가 9개와 1개 — 10개이니 100원짜리 1개로 바꿔요.","100원이 3개, 1원이 5개 — 305원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L04_challenge#10','math',2,1,'u1','L04','g2_1_math_u1_L04_challenge','lesson_challenge','M2-1-u1-C3',4,'essay','teacher','「삼백오」를 35가 아니라 305로 써야 하는 까닭을 친구에게 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u1-C3","difficulty":4,"kind":"essay","stem":"「삼백오」를 35가 아니라 305로 써야 하는 까닭을 친구에게 설명해 보세요.","answer_guide":{"answer":"삼백오는 100이 3개, 10이 0개, 1이 5개인 수이다. 35로 쓰면 10이 3개, 1이 5개인 두 자리 수가 되므로, 없는 십의 자리에 0을 써서 305로 써야 한다.","scoring_points":["100이 3개, 1이 5개라고 자리별로 말했는가","35는 다른 수(두 자리 수)라는 것을 말했는가","없는 자리에 0을 쓴다는 것을 말했는가"]},"explanation":["「삼백오」는 백의 자리 3, 십의 자리 0, 일의 자리 5예요.","35는 십의 자리 3인 다른 수예요.","없는 자리에는 0을 써서 자리를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#1','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',1,'mc','auto','382에서 십의 자리 숫자는 무엇인가요?',ARRAY['M2-1-u1-X08','M2-1-u1-X09']::text[],true,'{"seq":1,"concept":"M2-1-u1-C4","difficulty":1,"kind":"mc","stem":"382에서 십의 자리 숫자는 무엇인가요?","options":[{"t":"8","correct":true},{"t":"2","mis":"M2-1-u1-X08"},{"t":"80","mis":"M2-1-u1-X09"}],"explanation":["382는 백의 자리 3, 십의 자리 8, 일의 자리 2예요.","십의 자리 숫자는 8이에요.","자리는 왼쪽부터 백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv3":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#2','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',1,'mc','auto','382에서 숫자 8이 나타내는 값은 얼마인가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X08']::text[],true,'{"seq":2,"concept":"M2-1-u1-C4","difficulty":1,"kind":"mc","stem":"382에서 숫자 8이 나타내는 값은 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8","mis":"M2-1-u1-X09"},{"t":"800","mis":"M2-1-u1-X08"}],"explanation":["숫자 8은 십의 자리에 있어요.","십의 자리 8은 80을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv3":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#3','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',1,'mc','auto','456을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X08']::text[],true,'{"seq":3,"concept":"M2-1-u1-C4","difficulty":1,"kind":"mc","stem":"456을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"400 + 50 + 6","correct":true},{"t":"4 + 5 + 6","mis":"M2-1-u1-X09"},{"t":"400 + 60 + 5","mis":"M2-1-u1-X08"}],"explanation":["456은 백의 자리 4, 십의 자리 5, 일의 자리 6이에요.","각 자리의 값은 400, 50, 6 — 456 = 400 + 50 + 6.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv3":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#4','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',1,'sa','auto','573의 자릿값 표예요. 빈칸에 알맞은 값은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-1-u1-C4","difficulty":1,"kind":"sa","stem":"573의 자릿값 표예요. 빈칸에 알맞은 값은 얼마인가요?","answer":["70"],"explanation":["빈칸은 십의 자리예요.","십의 자리 숫자 7은 70을 나타내요.","나타내는 값 = 숫자 × 자리(100·10·1)."],"asset":{"type":"place_table","digits":[5,7,3],"values":[500,null,3],"mark":"t"},"variant_rule":{"pv3":{"ask":"table"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#5','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',2,'mc','auto','숫자 6이 60을 나타내는 수는 어느 것인가요?',ARRAY['M2-1-u1-X08']::text[],true,'{"seq":5,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"숫자 6이 60을 나타내는 수는 어느 것인가요?","options":[{"t":"365","correct":true},{"t":"637","mis":"M2-1-u1-X08"},{"t":"516","mis":"M2-1-u1-X08"}],"explanation":["60은 십의 자리 값이에요.","숫자 6이 십의 자리에 있는 수는 365예요.","숫자가 어느 자리에 있는지 먼저 찾아요."],"variant_rule":{"pv3":{"ask":"which","place":"t"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#6','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',2,'mc','auto','705에서 십의 자리 숫자는 무엇인가요?',ARRAY['M2-1-u1-X08']::text[],true,'{"seq":6,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"705에서 십의 자리 숫자는 무엇인가요?","options":[{"t":"0","correct":true},{"t":"5","mis":"M2-1-u1-X08"},{"t":"7","mis":"M2-1-u1-X08"}],"explanation":["705는 백의 자리 7, 십의 자리 0, 일의 자리 5예요.","십의 자리 숫자는 0이에요.","읽을 때 소리가 나지 않아도 자리는 있어요."],"variant_rule":{"pv3":{"ask":"digit","zero":true,"place":"t"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#7','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',2,'ox','auto','323에서 두 숫자 3이 나타내는 값은 같아요.',ARRAY['M2-1-u1-X09']::text[],true,'{"seq":7,"concept":"M2-1-u1-C4","difficulty":2,"kind":"ox","stem":"323에서 두 숫자 3이 나타내는 값은 같아요.","answer":"X","reason_options":[{"t":"앞의 3은 300, 뒤의 3은 3을 나타내니까","correct":true},{"t":"같은 숫자니까 값도 같아서","mis":"M2-1-u1-X09"}],"mis":"M2-1-u1-X09","explanation":["앞의 3은 백의 자리에 있어서 300이에요.","뒤의 3은 일의 자리에 있어서 3이에요.","그래서 틀린 말이에요 — 자리에 따라 값이 달라요."],"variant_rule":{"alt":[{"stem":"444에서 세 숫자 4가 나타내는 값은 400, 40, 4예요.","answer":"O","reason_options":[{"t":"백·십·일의 자리에 따라 값이 다르니까","correct":true},{"t":"같은 숫자는 모두 4를 나타내니까","mis":"M2-1-u1-X09"}],"explanation":["왼쪽 4는 백의 자리 — 400이에요.","가운데 4는 40, 오른쪽 4는 4예요.","그래서 맞는 말이에요."]},{"stem":"727에서 두 숫자 7이 나타내는 값은 모두 7이에요.","answer":"X","reason_options":[{"t":"앞의 7은 700, 뒤의 7은 7이니까","correct":true},{"t":"같은 숫자니까 값도 같아서","mis":"M2-1-u1-X09"}],"explanation":["앞의 7은 백의 자리라 700이에요.","뒤의 7은 일의 자리라 7이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#8','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',2,'match','auto','418의 각 숫자가 나타내는 값끼리 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u1-C4","difficulty":2,"kind":"match","stem":"418의 각 숫자가 나타내는 값끼리 이어 보세요.","pairs":[{"l":"4","r":"400"},{"l":"1","r":"10"},{"l":"8","r":"8"}],"mis":"M2-1-u1-X09","explanation":["4는 백의 자리라 400이에요.","1은 십의 자리라 10, 8은 일의 자리라 8이에요.","숫자 × 자리로 값을 찾아요."],"variant_rule":{"alt":[{"stem":"263의 각 숫자가 나타내는 값끼리 이어 보세요.","pairs":[{"l":"2","r":"200"},{"l":"6","r":"60"},{"l":"3","r":"3"}],"explanation":["2는 백의 자리라 200이에요.","6은 십의 자리라 60, 3은 일의 자리라 3이에요.","숫자 × 자리로 값을 찾아요."]},{"stem":"795의 각 숫자가 나타내는 값끼리 이어 보세요.","pairs":[{"l":"7","r":"700"},{"l":"9","r":"90"},{"l":"5","r":"5"}],"explanation":["7은 백의 자리라 700이에요.","9는 십의 자리라 90, 5는 일의 자리라 5예요.","숫자 × 자리로 값을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#9','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',2,'blank','auto','600 + 40 + 9 = (        )',ARRAY['M2-1-u1-X05','M2-1-u1-X06']::text[],true,'{"seq":9,"concept":"M2-1-u1-C4","difficulty":2,"kind":"blank","stem":"600 + 40 + 9 = (        )","options":[{"t":"649","correct":true},{"t":"600409","mis":"M2-1-u1-X05"},{"t":"946","mis":"M2-1-u1-X06"}],"explanation":["600은 백의 자리, 40은 십의 자리, 9는 일의 자리 값이에요.","백 6, 십 4, 일 9 — 649예요.","값을 이어 쓰지 않고 자리마다 숫자 하나씩 써요."],"variant_rule":{"alt":[{"stem":"300 + 20 + 8 = (        )","options":[{"t":"328","correct":true},{"t":"300208","mis":"M2-1-u1-X05"},{"t":"823","mis":"M2-1-u1-X06"}],"explanation":["300은 백, 20은 십, 8은 일의 자리 값이에요.","백 3, 십 2, 일 8 — 328이에요.","자리마다 숫자 하나씩 써요."]},{"stem":"800 + 5 = (        )","options":[{"t":"805","correct":true},{"t":"85","mis":"M2-1-u1-X04"},{"t":"8005","mis":"M2-1-u1-X05"}],"explanation":["800은 백의 자리, 5는 일의 자리 값이에요.","십의 자리에 0을 써서 805예요.","없는 자리에는 0을 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_basic#10','math',2,1,'u1','L05','g2_1_math_u1_L05_basic','lesson_basic','M2-1-u1-C4',3,'mc','auto','백의 자리 숫자가 나타내는 값이 가장 큰 수는 어느 것인가요?',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":10,"concept":"M2-1-u1-C4","difficulty":3,"kind":"mc","stem":"백의 자리 숫자가 나타내는 값이 가장 큰 수는 어느 것인가요?","options":[{"t":"712","correct":true},{"t":"698","mis":"M2-1-u1-X13"},{"t":"599","mis":"M2-1-u1-X13"}],"explanation":["백의 자리 숫자는 7, 6, 5예요.","7이 나타내는 700이 가장 커요.","십·일의 자리 숫자가 커도 백의 자리 값과는 상관없어요."],"variant_rule":{"alt":[{"stem":"십의 자리 숫자가 나타내는 값이 가장 큰 수는 어느 것인가요?","options":[{"t":"391","correct":true},{"t":"748","mis":"M2-1-u1-X08"},{"t":"529","mis":"M2-1-u1-X08"}],"explanation":["십의 자리 숫자는 9, 4, 2예요.","9가 나타내는 90이 가장 커요.","백의 자리가 아니라 「십의 자리」를 봐요."]},{"stem":"일의 자리 숫자가 나타내는 값이 가장 큰 수는 어느 것인가요?","options":[{"t":"108","correct":true},{"t":"901","mis":"M2-1-u1-X08"},{"t":"560","mis":"M2-1-u1-X08"}],"explanation":["일의 자리 숫자는 8, 1, 0이에요.","8이 가장 커요.","맨 오른쪽이 일의 자리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#1','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',2,'mc','auto','264에서 6은 어느 자리 숫자이고, 얼마를 나타내나요?',ARRAY['M2-1-u1-X09','M2-1-u1-X08']::text[],true,'{"seq":1,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"264에서 6은 어느 자리 숫자이고, 얼마를 나타내나요?","options":[{"t":"십의 자리, 60","correct":true},{"t":"십의 자리, 6","mis":"M2-1-u1-X09"},{"t":"일의 자리, 6","mis":"M2-1-u1-X08"}],"explanation":["264는 백 2, 십 6, 일 4예요.","6은 십의 자리 숫자이고 60을 나타내요.","자리를 찾고 나서 값을 말해요."],"variant_rule":{"alt":[{"stem":"518에서 5는 어느 자리 숫자이고, 얼마를 나타내나요?","options":[{"t":"백의 자리, 500","correct":true},{"t":"백의 자리, 5","mis":"M2-1-u1-X09"},{"t":"일의 자리, 5","mis":"M2-1-u1-X08"}],"explanation":["518은 백 5, 십 1, 일 8이에요.","5는 백의 자리 숫자이고 500을 나타내요.","자리를 찾고 나서 값을 말해요."]},{"stem":"937에서 3은 어느 자리 숫자이고, 얼마를 나타내나요?","options":[{"t":"십의 자리, 30","correct":true},{"t":"십의 자리, 3","mis":"M2-1-u1-X09"},{"t":"백의 자리, 300","mis":"M2-1-u1-X08"}],"explanation":["937은 백 9, 십 3, 일 7이에요.","3은 십의 자리 숫자이고 30을 나타내요.","자리를 찾고 나서 값을 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#2','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',2,'sa','auto','937에서 숫자 9가 나타내는 값은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u1-C4","difficulty":2,"kind":"sa","stem":"937에서 숫자 9가 나타내는 값은 얼마인가요?","answer":["900"],"explanation":["숫자 9는 백의 자리에 있어요.","백의 자리 9는 900을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv3":{"ask":"value","place":"h"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#3','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',3,'mc','auto','숫자 5가 나타내는 값이 가장 큰 수는 어느 것인가요?',ARRAY['M2-1-u1-X08']::text[],true,'{"seq":3,"concept":"M2-1-u1-C4","difficulty":3,"kind":"mc","stem":"숫자 5가 나타내는 값이 가장 큰 수는 어느 것인가요?","options":[{"t":"523","correct":true},{"t":"352","mis":"M2-1-u1-X08"},{"t":"235","mis":"M2-1-u1-X08"}],"explanation":["523의 5는 백의 자리라 500이에요.","352의 5는 50, 235의 5는 5예요.","숫자는 같아도 높은 자리에 있을수록 값이 커요."],"variant_rule":{"alt":[{"stem":"숫자 4가 나타내는 값이 가장 작은 수는 어느 것인가요?","options":[{"t":"174","correct":true},{"t":"481","mis":"M2-1-u1-X08"},{"t":"346","mis":"M2-1-u1-X08"}],"explanation":["174의 4는 일의 자리라 4예요.","481의 4는 400, 346의 4는 40이에요.","낮은 자리에 있을수록 값이 작아요."]},{"stem":"숫자 8이 80을 나타내는 수는 어느 것인가요?","options":[{"t":"283","correct":true},{"t":"832","mis":"M2-1-u1-X08"},{"t":"318","mis":"M2-1-u1-X08"}],"explanation":["80은 십의 자리 값이에요.","숫자 8이 십의 자리에 있는 수는 283이에요.","숫자가 어느 자리에 있는지 먼저 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#4','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',3,'mc','auto','800 + 7은 얼마인가요?',ARRAY['M2-1-u1-X04','M2-1-u1-X05']::text[],true,'{"seq":4,"concept":"M2-1-u1-C4","difficulty":3,"kind":"mc","stem":"800 + 7은 얼마인가요?","options":[{"t":"807","correct":true},{"t":"87","mis":"M2-1-u1-X04"},{"t":"8007","mis":"M2-1-u1-X05"}],"explanation":["800은 백의 자리, 7은 일의 자리 값이에요.","십의 자리에 0을 써서 807이에요.","없는 자리에는 0을 써요."],"variant_rule":{"alt":[{"stem":"500 + 60은 얼마인가요?","options":[{"t":"560","correct":true},{"t":"56","mis":"M2-1-u1-X04"},{"t":"50060","mis":"M2-1-u1-X05"}],"explanation":["500은 백, 60은 십의 자리 값이에요.","일의 자리에 0을 써서 560이에요.","없는 자리에는 0을 써요."]},{"stem":"900 + 30 + 0은 얼마인가요?","options":[{"t":"930","correct":true},{"t":"93","mis":"M2-1-u1-X04"},{"t":"900300","mis":"M2-1-u1-X05"}],"explanation":["900은 백, 30은 십, 0은 일의 자리 값이에요.","백 9, 십 3, 일 0 — 930이에요.","0도 자리를 지켜요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#5','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',3,'error','auto','친구들이 555에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X08']::text[],true,'{"seq":5,"concept":"M2-1-u1-C4","difficulty":3,"kind":"error","stem":"친구들이 555에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤: 세 숫자 5는 모두 5를 나타내.","correct":true,"mis_target":"M2-1-u1-X09"},{"t":"시우: 맨 앞의 5는 500을 나타내.","mis":"M2-1-u1-X08"},{"t":"나은: 555는 500 + 50 + 5야.","mis":"M2-1-u1-X09"}],"explanation":["맨 앞 5는 500, 가운데 5는 50, 맨 뒤 5는 5를 나타내요.","세 숫자 5의 값은 모두 달라요.","하윤이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"친구들이 606에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하: 두 숫자 6은 모두 600을 나타내.","correct":true,"mis_target":"M2-1-u1-X09"},{"t":"라온: 십의 자리 숫자는 0이야.","mis":"M2-1-u1-X08"},{"t":"세아: 606은 600 + 6이야.","mis":"M2-1-u1-X04"}],"explanation":["앞의 6은 600, 뒤의 6은 6을 나타내요.","두 숫자 6의 값은 달라요.","도하가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#6','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',3,'mc','auto','십의 자리 숫자가 가장 큰 수는 어느 것인가요?',ARRAY['M2-1-u1-X08']::text[],true,'{"seq":6,"concept":"M2-1-u1-C4","difficulty":3,"kind":"mc","stem":"십의 자리 숫자가 가장 큰 수는 어느 것인가요?","options":[{"t":"391","correct":true},{"t":"748","mis":"M2-1-u1-X08"},{"t":"529","mis":"M2-1-u1-X08"}],"explanation":["십의 자리 숫자는 391이 9, 748이 4, 529가 2예요.","십의 자리 숫자가 가장 큰 수는 391이에요.","가장 큰 수를 묻는 게 아니라 「십의 자리 숫자」를 물었어요."],"variant_rule":{"alt":[{"stem":"일의 자리 숫자가 가장 큰 수는 어느 것인가요?","options":[{"t":"219","correct":true},{"t":"970","mis":"M2-1-u1-X08"},{"t":"583","mis":"M2-1-u1-X08"}],"explanation":["일의 자리 숫자는 219가 9, 970이 0, 583이 3이에요.","일의 자리 숫자가 가장 큰 수는 219예요.","가장 큰 수를 묻는 게 아니라 「일의 자리 숫자」를 물었어요."]},{"stem":"백의 자리 숫자가 가장 작은 수는 어느 것인가요?","options":[{"t":"398","correct":true},{"t":"401","mis":"M2-1-u1-X08"},{"t":"520","mis":"M2-1-u1-X08"}],"explanation":["백의 자리 숫자는 3, 4, 5예요.","백의 자리 숫자가 가장 작은 수는 398이에요.","맨 왼쪽이 백의 자리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#7','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',3,'sa','auto','백의 자리 숫자는 2, 십의 자리 숫자는 6, 일의 자리 숫자는 0인 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u1-C4","difficulty":3,"kind":"sa","stem":"백의 자리 숫자는 2, 십의 자리 숫자는 6, 일의 자리 숫자는 0인 수를 쓰세요.","answer":["260"],"explanation":["백 2, 십 6, 일 0이에요.","수로 쓰면 260이에요.","일의 자리 0도 꼭 써요."],"variant_rule":{"alt":[{"stem":"백의 자리 숫자는 9, 십의 자리 숫자는 0, 일의 자리 숫자는 4인 수를 쓰세요.","answer":["904"],"explanation":["백 9, 십 0, 일 4예요.","수로 쓰면 904예요.","십의 자리 0도 꼭 써요."]},{"stem":"백의 자리 숫자는 3, 십의 자리 숫자는 8, 일의 자리 숫자는 1인 수를 쓰세요.","answer":["381"],"explanation":["백 3, 십 8, 일 1이에요.","수로 쓰면 381이에요.","백·십·일 차례로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#8','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',4,'mc','auto','□76에서 □가 나타내는 값은 500이에요. 이 수에서 7이 나타내는 값과 □가 나타내는 값을 모으면 얼마인가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X08']::text[],true,'{"seq":8,"concept":"M2-1-u1-C4","difficulty":4,"kind":"mc","stem":"□76에서 □가 나타내는 값은 500이에요. 이 수에서 7이 나타내는 값과 □가 나타내는 값을 모으면 얼마인가요?","options":[{"t":"570","correct":true},{"t":"12","mis":"M2-1-u1-X09"},{"t":"507","mis":"M2-1-u1-X08"}],"explanation":["□는 백의 자리라서 5예요 — 수는 576이에요.","7은 십의 자리라 70을 나타내요.","500과 70을 모으면 570이에요."],"variant_rule":{"alt":[{"stem":"3□8에서 □가 나타내는 값은 40이에요. 이 수에서 3이 나타내는 값과 □가 나타내는 값을 모으면 얼마인가요?","options":[{"t":"340","correct":true},{"t":"7","mis":"M2-1-u1-X09"},{"t":"304","mis":"M2-1-u1-X08"}],"explanation":["□는 십의 자리라서 4예요 — 수는 348이에요.","3은 백의 자리라 300을 나타내요.","300과 40을 모으면 340이에요."]},{"stem":"6□2에서 □가 나타내는 값은 90이에요. 이 수에서 2가 나타내는 값과 □가 나타내는 값을 모으면 얼마인가요?","options":[{"t":"92","correct":true},{"t":"11","mis":"M2-1-u1-X09"},{"t":"290","mis":"M2-1-u1-X08"}],"explanation":["□는 십의 자리라서 9예요 — 수는 692예요.","2는 일의 자리라 2를 나타내요.","90과 2를 모으면 92예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#9','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',4,'mc','auto','십의 자리 숫자가 나타내는 값과 일의 자리 숫자가 나타내는 값이 같은 수는 어느 것인가요?',ARRAY['M2-1-u1-X09']::text[],true,'{"seq":9,"concept":"M2-1-u1-C4","difficulty":4,"kind":"mc","stem":"십의 자리 숫자가 나타내는 값과 일의 자리 숫자가 나타내는 값이 같은 수는 어느 것인가요?","options":[{"t":"300","correct":true},{"t":"330","mis":"M2-1-u1-X09"},{"t":"303","mis":"M2-1-u1-X09"}],"explanation":["330은 십의 자리 값 30, 일의 자리 값 0이라 달라요.","303은 십의 자리 값 0, 일의 자리 값 3이라 달라요.","300은 둘 다 0이라 같아요 — 숫자가 같아도 자리가 다르면 값이 달라요."],"variant_rule":{"alt":[{"stem":"백의 자리 숫자가 나타내는 값과 십의 자리 숫자가 나타내는 값을 모으면 450인 수는 어느 것인가요?","options":[{"t":"452","correct":true},{"t":"542","mis":"M2-1-u1-X08"},{"t":"405","mis":"M2-1-u1-X09"}],"explanation":["452는 400과 50 — 모으면 450이에요.","542는 500과 40, 405는 400과 0이에요.","자리마다 값을 먼저 찾아요."]},{"stem":"일의 자리 숫자가 나타내는 값이 십의 자리 숫자가 나타내는 값보다 큰 수는 어느 것인가요?","options":[{"t":"208","correct":true},{"t":"281","mis":"M2-1-u1-X09"},{"t":"120","mis":"M2-1-u1-X09"}],"explanation":["208은 십의 자리 값 0, 일의 자리 값 8 — 일의 자리가 커요.","281은 80과 1, 120은 20과 0이라 십의 자리가 커요.","숫자만이 아니라 나타내는 값으로 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L05_challenge#10','math',2,1,'u1','L05','g2_1_math_u1_L05_challenge','lesson_challenge','M2-1-u1-C4',4,'essay','teacher','333에서 세 숫자 3이 나타내는 값이 어떻게 다른지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u1-C4","difficulty":4,"kind":"essay","stem":"333에서 세 숫자 3이 나타내는 값이 어떻게 다른지 설명해 보세요.","answer_guide":{"answer":"맨 앞 3은 백의 자리라 300, 가운데 3은 십의 자리라 30, 맨 뒤 3은 일의 자리라 3을 나타낸다. 같은 숫자라도 자리에 따라 값이 다르다.","scoring_points":["세 숫자의 자리를 바르게 말했는가","300·30·3을 바르게 썼는가","「자리에 따라 값이 다르다」는 까닭을 말했는가"]},"explanation":["333 = 300 + 30 + 3이에요.","같은 3이라도 백·십·일의 자리에 따라 300·30·3이에요.","숫자 × 자리로 값을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#1','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',1,'mc','auto','100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":1,"concept":"M2-1-u1-C5","difficulty":1,"kind":"mc","stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"600","correct":true},{"t":"510","mis":"M2-1-u1-X11"},{"t":"501","mis":"M2-1-u1-X11"}],"explanation":["100씩 뛰면 백의 자리 숫자가 1씩 커져요.","500에서 100만큼 뛰면 600이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[200,300,400,500,null],"step":100},"variant_rule":{"skip3":{"ask":"next","step":[100]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#2','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',1,'sa','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u1-C5","difficulty":1,"kind":"sa","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","answer":["652"],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","642에서 10만큼 뛰면 652예요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[612,622,632,642,null],"step":10},"variant_rule":{"skip3":{"ask":"next","step":[10]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#3','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',1,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":3,"concept":"M2-1-u1-C5","difficulty":1,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"349","correct":true},{"t":"358","mis":"M2-1-u1-X11"},{"t":"448","mis":"M2-1-u1-X11"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","348에서 1만큼 뛰면 349예요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[345,346,347,348,null],"step":1},"variant_rule":{"skip3":{"ask":"next","step":[1]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#4','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',1,'mc','auto','999보다 1만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X12']::text[],true,'{"seq":4,"concept":"M2-1-u1-C5","difficulty":1,"kind":"mc","stem":"999보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9910","mis":"M2-1-u1-X01"},{"t":"998","mis":"M2-1-u1-X12"}],"explanation":["999 다음 수예요.","일·십·백의 자리가 모두 넘어가 1000이 돼요.","1000은 「천」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"990보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9100","mis":"M2-1-u1-X01"},{"t":"991","mis":"M2-1-u1-X12"}],"explanation":["990에서 10만큼 뛰어요.","십의 자리가 넘어가고 백의 자리도 넘어가 1000이에요.","숫자를 이어 붙이지 않아요."]},{"stem":"900보다 100만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9100","mis":"M2-1-u1-X01"},{"t":"910","mis":"M2-1-u1-X12"}],"explanation":["100이 9개에 1개를 더하면 10개예요.","100이 10개이면 1000이에요.","1000은 「천」이라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#5','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',2,'mc','auto','얼마씩 뛰어 세었나요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":5,"concept":"M2-1-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 뛰어 세었나요?","options":[{"t":"10씩","correct":true},{"t":"1씩","mis":"M2-1-u1-X12"},{"t":"100씩","mis":"M2-1-u1-X12"}],"explanation":["430, 440, 450 … 하고 십의 자리 숫자만 1씩 커져요.","그래서 10씩 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[430,440,450,460,470],"step":null},"variant_rule":{"skip3":{"ask":"step","step":[1,10,100],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#6','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',2,'mc','auto','10씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":6,"concept":"M2-1-u1-C5","difficulty":2,"kind":"mc","stem":"10씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"730","correct":true},{"t":"731","mis":"M2-1-u1-X11"},{"t":"630","mis":"M2-1-u1-X11"}],"explanation":["10씩 거꾸로 뛰면 십의 자리 숫자가 1씩 작아져요.","740에서 10만큼 거꾸로 뛰면 730이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[750,740,null,720,710],"step":10,"dir":"down"},"variant_rule":{"skip3":{"ask":"blank","step":[10],"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#7','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',2,'mc','auto','1000을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u1-X07','M2-1-u1-X02']::text[],true,'{"seq":7,"concept":"M2-1-u1-C5","difficulty":2,"kind":"mc","stem":"1000을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"천","correct":true},{"t":"일영영영","mis":"M2-1-u1-X07"},{"t":"십백","mis":"M2-1-u1-X02"}],"explanation":["1000은 100이 10개인 수예요.","「천」이라고 읽어요.","숫자를 하나씩 따로 읽지 않아요."],"variant_rule":{"alt":[{"stem":"「천」을 수로 쓰면 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"100","mis":"M2-1-u1-X12"},{"t":"10000","mis":"M2-1-u1-X02"}],"explanation":["「천」은 100이 10개예요.","수로 쓰면 1000이에요.","1 뒤에 0을 세 개 써요."]},{"stem":"1000에 대한 설명으로 바른 것은 어느 것인가요?","options":[{"t":"999보다 1 큰 수예요.","correct":true},{"t":"100이 1개인 수예요.","mis":"M2-1-u1-X02"},{"t":"990보다 1 큰 수예요.","mis":"M2-1-u1-X12"}],"explanation":["1000은 999 바로 다음 수예요.","100이 10개인 수이기도 해요.","990보다는 10 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#8','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',2,'ox','auto','380부터 10씩 뛰어 세면 380, 390, 3100이에요.',ARRAY['M2-1-u1-X01']::text[],true,'{"seq":8,"concept":"M2-1-u1-C5","difficulty":2,"kind":"ox","stem":"380부터 10씩 뛰어 세면 380, 390, 3100이에요.","answer":"X","reason_options":[{"t":"390 다음은 400이니까","correct":true},{"t":"9 다음에 10을 붙이면 되니까","mis":"M2-1-u1-X01"}],"mis":"M2-1-u1-X01","explanation":["390에서 10을 더 뛰면 십의 자리가 10이 돼요.","십의 자리 10은 백의 자리 1로 넘어가 400이에요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"597부터 1씩 뛰어 세면 597, 598, 599, 600이에요.","answer":"O","reason_options":[{"t":"599 다음은 600이니까","correct":true},{"t":"599 다음은 5910이니까","mis":"M2-1-u1-X01"}],"explanation":["599에서 1을 더 뛰면 일의 자리가 10이 돼요.","십·백의 자리로 넘어가 600이에요.","그래서 맞는 말이에요."]},{"stem":"800부터 100씩 거꾸로 뛰어 세면 800, 700, 600이에요.","answer":"O","reason_options":[{"t":"백의 자리 숫자가 1씩 작아지니까","correct":true},{"t":"거꾸로 뛰면 백의 자리가 커지니까","mis":"M2-1-u1-X12"}],"explanation":["100씩 거꾸로 뛰면 백의 자리 숫자가 1씩 작아져요.","800, 700, 600이에요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#9','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',2,'match','auto','얼마씩 뛰어 센 것인지 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u1-C5","difficulty":2,"kind":"match","stem":"얼마씩 뛰어 센 것인지 이어 보세요.","pairs":[{"l":"211, 212, 213","r":"1씩"},{"l":"211, 221, 231","r":"10씩"},{"l":"211, 311, 411","r":"100씩"}],"mis":"M2-1-u1-X12","explanation":["일의 자리만 바뀌면 1씩이에요.","십의 자리만 바뀌면 10씩, 백의 자리만 바뀌면 100씩이에요.","바뀐 자리를 보면 몇씩인지 보여요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 얼마씩 뛰어 센 것인지 이어 보세요.","pairs":[{"l":"504, 604, 704","r":"100씩"},{"l":"504, 505, 506","r":"1씩"},{"l":"504, 514, 524","r":"10씩"}],"explanation":["백의 자리만 바뀌면 100씩이에요.","일의 자리만 바뀌면 1씩, 십의 자리만 바뀌면 10씩이에요.","바뀐 자리를 보면 몇씩인지 보여요."]},{"stem":"얼마씩 거꾸로 뛰어 센 것인지 이어 보세요.","pairs":[{"l":"860, 850, 840","r":"10씩"},{"l":"860, 760, 660","r":"100씩"},{"l":"860, 859, 858","r":"1씩"}],"explanation":["십의 자리만 작아지면 10씩이에요.","백의 자리만 작아지면 100씩, 일의 자리만 작아지면 1씩이에요.","바뀐 자리를 보면 몇씩인지 보여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_basic#10','math',2,1,'u1','L06','g2_1_math_u1_L06_basic','lesson_basic','M2-1-u1-C5',3,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X11']::text[],true,'{"seq":10,"concept":"M2-1-u1-C5","difficulty":3,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"400","correct":true},{"t":"3100","mis":"M2-1-u1-X01"},{"t":"391","mis":"M2-1-u1-X11"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","390에서 10만큼 뛰면 400이에요.","십의 자리가 10이 되면 바로 윗자리가 1 커지고 십의 자리는 0이 돼요."],"asset":{"type":"jump_row","cells":[370,380,390,null,410],"step":10},"variant_rule":{"skip3":{"ask":"blank","step":[10],"cross":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#1','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',2,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X11']::text[],true,'{"seq":1,"concept":"M2-1-u1-C5","difficulty":2,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9910","mis":"M2-1-u1-X01"},{"t":"1009","mis":"M2-1-u1-X11"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","999에서 1만큼 뛰면 1000이에요.","일의 자리가 10이 되면 바로 윗자리가 1 커지고 일의 자리는 0이 돼요."],"asset":{"type":"jump_row","cells":[996,997,998,999,null],"step":1},"variant_rule":{"skip3":{"ask":"next","step":[1,10],"cross":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#2','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',2,'sa','auto','100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u1-C5","difficulty":2,"kind":"sa","stem":"100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","answer":["600"],"explanation":["100씩 거꾸로 뛰면 백의 자리 숫자가 1씩 작아져요.","700에서 100만큼 거꾸로 뛰면 600이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[900,800,700,null,500],"step":100,"dir":"down"},"variant_rule":{"skip3":{"ask":"blank","step":[100],"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#3','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',3,'mc','auto','485에서 10씩 3번 뛰어 센 수는 무엇인가요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":3,"concept":"M2-1-u1-C5","difficulty":3,"kind":"mc","stem":"485에서 10씩 3번 뛰어 센 수는 무엇인가요?","options":[{"t":"515","correct":true},{"t":"488","mis":"M2-1-u1-X12"},{"t":"785","mis":"M2-1-u1-X12"}],"explanation":["485, 495, 505, 515 — 10씩 3번이에요.","495 다음은 십의 자리가 넘어가 505예요.","10씩 3번은 1씩 3번, 100씩 3번과 달라요."],"variant_rule":{"alt":[{"stem":"762에서 100씩 2번 뛰어 센 수는 무엇인가요?","options":[{"t":"962","correct":true},{"t":"782","mis":"M2-1-u1-X12"},{"t":"764","mis":"M2-1-u1-X12"}],"explanation":["762, 862, 962 — 100씩 2번이에요.","백의 자리만 1씩 커져요.","100씩 2번은 10씩 2번, 1씩 2번과 달라요."]},{"stem":"298에서 1씩 4번 뛰어 센 수는 무엇인가요?","options":[{"t":"302","correct":true},{"t":"338","mis":"M2-1-u1-X12"},{"t":"2912","mis":"M2-1-u1-X01"}],"explanation":["298, 299, 300, 301, 302 — 1씩 4번이에요.","299 다음은 300이에요.","자리가 넘어가는 곳을 조심해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#4','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',3,'mc','auto','어떤 수에서 100씩 4번 뛰어 세었더니 800이 되었어요. 어떤 수는 무엇인가요?',ARRAY['M2-1-u1-X15','M2-1-u1-X12']::text[],true,'{"seq":4,"concept":"M2-1-u1-C5","difficulty":3,"kind":"mc","stem":"어떤 수에서 100씩 4번 뛰어 세었더니 800이 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"400","correct":true},{"t":"1200","mis":"M2-1-u1-X15"},{"t":"796","mis":"M2-1-u1-X12"}],"explanation":["800에서 100씩 거꾸로 4번 뛰어 세요.","800, 700, 600, 500, 400 — 어떤 수는 400이에요.","「어떤 수에서 뛰어 셌다」면 거꾸로 세어 찾아요."],"variant_rule":{"alt":[{"stem":"어떤 수에서 10씩 3번 뛰어 세었더니 500이 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"470","correct":true},{"t":"530","mis":"M2-1-u1-X15"},{"t":"497","mis":"M2-1-u1-X12"}],"explanation":["500에서 10씩 거꾸로 3번 뛰어 세요.","500, 490, 480, 470 — 어떤 수는 470이에요.","「어떤 수에서 뛰어 셌다」면 거꾸로 세어 찾아요."]},{"stem":"어떤 수에서 1씩 5번 뛰어 세었더니 603이 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"598","correct":true},{"t":"608","mis":"M2-1-u1-X15"},{"t":"553","mis":"M2-1-u1-X12"}],"explanation":["603에서 1씩 거꾸로 5번 뛰어 세요.","603, 602, 601, 600, 599, 598 — 어떤 수는 598이에요.","「어떤 수에서 뛰어 셌다」면 거꾸로 세어 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#5','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',3,'mc','auto','얼마씩 거꾸로 뛰어 세었나요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":5,"concept":"M2-1-u1-C5","difficulty":3,"kind":"mc","stem":"얼마씩 거꾸로 뛰어 세었나요?","options":[{"t":"100씩","correct":true},{"t":"10씩","mis":"M2-1-u1-X12"},{"t":"1씩","mis":"M2-1-u1-X12"}],"explanation":["505, 405, 305 … 하고 백의 자리 숫자만 1씩 작아져요.","그래서 100씩 거꾸로 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[505,405,305,205,105],"step":null,"dir":"down"},"variant_rule":{"skip3":{"ask":"step","step":[1,10,100],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#6','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',3,'error','auto','590부터 뛰어 센 다음 수를 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X11']::text[],true,'{"seq":6,"concept":"M2-1-u1-C5","difficulty":3,"kind":"error","stem":"590부터 뛰어 센 다음 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"서아: 10씩 뛰면 590 다음은 5100이야.","correct":true,"mis_target":"M2-1-u1-X01"},{"t":"주원: 1씩 뛰면 590 다음은 591이야.","mis":"M2-1-u1-X11"},{"t":"라온: 100씩 뛰면 590 다음은 690이야.","mis":"M2-1-u1-X11"}],"explanation":["590에서 10을 더 뛰면 십의 자리가 10이 돼요.","백의 자리로 넘어가 600이에요.","서아가 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"400부터 거꾸로 뛰어 센 다음 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호: 10씩 거꾸로 뛰면 400 다음은 490이야.","correct":true,"mis_target":"M2-1-u1-X01"},{"t":"하린: 1씩 거꾸로 뛰면 400 다음은 399야.","mis":"M2-1-u1-X11"},{"t":"도윤: 100씩 거꾸로 뛰면 400 다음은 300이야.","mis":"M2-1-u1-X11"}],"explanation":["400에서 10을 거꾸로 뛰면 백의 자리에서 하나를 빌려 와야 해요.","400보다 10 작은 수는 390이에요.","지호가 잘못 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#7','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',3,'ox','auto','604부터 1씩 거꾸로 5번 뛰어 세면 600이에요.',ARRAY['M2-1-u1-X01']::text[],true,'{"seq":7,"concept":"M2-1-u1-C5","difficulty":3,"kind":"ox","stem":"604부터 1씩 거꾸로 5번 뛰어 세면 600이에요.","answer":"X","reason_options":[{"t":"604, 603, 602, 601, 600, 599라서 599이니까","correct":true},{"t":"일의 자리 4에서 거꾸로 세면 0에서 멈추니까","mis":"M2-1-u1-X01"}],"mis":"M2-1-u1-X01","explanation":["1씩 거꾸로 5번이면 603, 602, 601, 600, 599예요.","600 다음 한 번 더 세면 599가 돼요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"395부터 1씩 5번 뛰어 세면 400이에요.","answer":"O","reason_options":[{"t":"396, 397, 398, 399, 400이니까","correct":true},{"t":"395, 396, 397, 398, 399라서","mis":"M2-1-u1-X12"}],"explanation":["1씩 5번이면 396, 397, 398, 399, 400이에요.","399 다음은 400이에요.","그래서 맞는 말이에요."]},{"stem":"980부터 10씩 2번 뛰어 세면 9100이에요.","answer":"X","reason_options":[{"t":"990, 1000이라서 1000이니까","correct":true},{"t":"98 다음은 99, 910이라서","mis":"M2-1-u1-X01"}],"explanation":["980, 990, 1000이에요.","990 다음은 1000이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#8','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',4,'mc','auto','규칙에 따라 뛰어 세었어요. 235, 245, 255, ★, 275 — ★보다 100만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":8,"concept":"M2-1-u1-C5","difficulty":4,"kind":"mc","stem":"규칙에 따라 뛰어 세었어요. 235, 245, 255, ★, 275 — ★보다 100만큼 더 큰 수는 무엇인가요?","options":[{"t":"365","correct":true},{"t":"275","mis":"M2-1-u1-X12"},{"t":"266","mis":"M2-1-u1-X12"}],"explanation":["10씩 뛰어 세었어요 — ★은 265예요.","265보다 100 큰 수는 365예요.","먼저 규칙으로 ★을 찾고 나서 묻는 말을 풀어요."],"variant_rule":{"alt":[{"stem":"규칙에 따라 뛰어 세었어요. 708, 608, 508, ★, 308 — ★보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"418","correct":true},{"t":"508","mis":"M2-1-u1-X12"},{"t":"409","mis":"M2-1-u1-X12"}],"explanation":["100씩 거꾸로 뛰어 세었어요 — ★은 408이에요.","408보다 10 큰 수는 418이에요.","먼저 규칙으로 ★을 찾아요."]},{"stem":"규칙에 따라 뛰어 세었어요. 497, 498, 499, ★, 501 — ★보다 10만큼 더 작은 수는 무엇인가요?","options":[{"t":"490","correct":true},{"t":"510","mis":"M2-1-u1-X15"},{"t":"499","mis":"M2-1-u1-X12"}],"explanation":["1씩 뛰어 세었어요 — ★은 500이에요.","500보다 10 작은 수는 490이에요.","먼저 규칙으로 ★을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#9','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',4,'mc','auto','740부터 10씩 뛰어 셀 때, 800보다 큰 수 가운데 처음 나오는 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":9,"concept":"M2-1-u1-C5","difficulty":4,"kind":"mc","stem":"740부터 10씩 뛰어 셀 때, 800보다 큰 수 가운데 처음 나오는 수는 무엇인가요?","options":[{"t":"810","correct":true},{"t":"801","mis":"M2-1-u1-X11"},{"t":"900","mis":"M2-1-u1-X11"}],"explanation":["740, 750, … 790, 800, 810이에요.","800 다음에 나오는 수가 810이에요.","10씩 뛰면 일의 자리는 그대로 0이에요."],"variant_rule":{"alt":[{"stem":"365부터 100씩 뛰어 셀 때, 800보다 큰 수 가운데 처음 나오는 수는 무엇인가요?","options":[{"t":"865","correct":true},{"t":"801","mis":"M2-1-u1-X11"},{"t":"900","mis":"M2-1-u1-X11"}],"explanation":["365, 465, 565, 665, 765, 865예요.","800보다 큰 수 가운데 처음 나오는 수는 865예요.","100씩 뛰면 십·일의 자리는 그대로예요."]},{"stem":"893부터 1씩 뛰어 셀 때, 900보다 큰 수 가운데 처음 나오는 수는 무엇인가요?","options":[{"t":"901","correct":true},{"t":"910","mis":"M2-1-u1-X11"},{"t":"900","mis":"M2-1-u1-X13"}],"explanation":["893, … 899, 900, 901이에요.","900보다 큰 수 가운데 처음 나오는 수는 901이에요.","900은 900보다 크지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L06_challenge#10','math',2,1,'u1','L06','g2_1_math_u1_L06_challenge','lesson_challenge','M2-1-u1-C5',4,'essay','teacher','990부터 10씩 뛰어 세면 다음 수는 무엇인지 쓰고, 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u1-C5","difficulty":4,"kind":"essay","stem":"990부터 10씩 뛰어 세면 다음 수는 무엇인지 쓰고, 그 까닭을 설명해 보세요.","answer_guide":{"answer":"1000. 990에서 10을 더하면 십의 자리가 10이 되어 백의 자리로 넘어가고, 백의 자리도 10이 되어 천의 자리로 넘어가므로 1000이 된다.","scoring_points":["다음 수를 1000이라고 바르게 썼는가","십의 자리가 10이 되어 윗자리로 넘어간다고 말했는가","9100처럼 이어 쓰지 않는 까닭을 말했는가"]},"explanation":["990 다음 10씩이면 십의 자리가 10이 돼요.","10은 윗자리로 넘어가고, 백의 자리도 10이 되어 1000이에요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#1','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',1,'mc','auto','754와 745 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":1,"concept":"M2-1-u1-C6","difficulty":1,"kind":"mc","stem":"754와 745 중에서 더 큰 수는 무엇인가요?","options":[{"t":"754","correct":true},{"t":"745","mis":"M2-1-u1-X13"}],"explanation":["백의 자리가 같아요.","십의 자리를 보면 5는 4보다 커요 — 더 큰 수는 754예요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp3d":{"ask":"big","same":"h"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#2','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',1,'mc','auto','169와 168 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":2,"concept":"M2-1-u1-C6","difficulty":1,"kind":"mc","stem":"169와 168 중에서 더 큰 수는 무엇인가요?","options":[{"t":"169","correct":true},{"t":"168","mis":"M2-1-u1-X13"}],"explanation":["백의 자리와 십의 자리가 같아요.","일의 자리를 보면 9는 8보다 커요 — 더 큰 수는 169예요.","높은 자리가 같을 때만 낮은 자리를 봐요."],"variant_rule":{"cmp3d":{"ask":"big","same":"ht"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#3','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',1,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-1-u1-X14']::text[],true,'{"seq":3,"concept":"M2-1-u1-C6","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"412 > 398","correct":true},{"t":"412 < 398","mis":"M2-1-u1-X14"}],"explanation":["백의 자리에서 처음으로 달라요 — 4는 3보다 커요.","그래서 412는 398보다 커요 — 412 > 398.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp3d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#4','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',1,'mc','auto','561과 516 중에서 더 작은 수는 무엇인가요?',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":4,"concept":"M2-1-u1-C6","difficulty":1,"kind":"mc","stem":"561과 516 중에서 더 작은 수는 무엇인가요?","options":[{"t":"516","correct":true},{"t":"561","mis":"M2-1-u1-X13"}],"explanation":["백의 자리가 같아요.","십의 자리를 보면 1은 6보다 작아요 — 더 작은 수는 516이에요.","높은 자리부터 차례로 견주어요."],"variant_rule":{"cmp3d":{"ask":"small","same":"h"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#5','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',2,'mc','auto','529, 592, 295 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],true,'{"seq":5,"concept":"M2-1-u1-C6","difficulty":2,"kind":"mc","stem":"529, 592, 295 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"592","correct":true},{"t":"529","mis":"M2-1-u1-X13"},{"t":"295","mis":"M2-1-u1-X15"}],"explanation":["높은 자리(백의 자리)부터 차례로 견주어요.","가장 큰 수는 592예요.","일의 자리가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp3d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#6','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',2,'mc','auto','403, 340, 430 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],true,'{"seq":6,"concept":"M2-1-u1-C6","difficulty":2,"kind":"mc","stem":"403, 340, 430 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"340","correct":true},{"t":"403","mis":"M2-1-u1-X13"},{"t":"430","mis":"M2-1-u1-X15"}],"explanation":["높은 자리(백의 자리)부터 차례로 견주어요.","가장 작은 수는 340이에요.","일의 자리가 작다고 작은 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp3d":{"ask":"min3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#7','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',2,'ox','auto','196과 169 가운데 일의 자리 숫자가 큰 169가 더 커요.',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":7,"concept":"M2-1-u1-C6","difficulty":2,"kind":"ox","stem":"196과 169 가운데 일의 자리 숫자가 큰 169가 더 커요.","answer":"X","reason_options":[{"t":"십의 자리 9가 6보다 커서 196이 더 크니까","correct":true},{"t":"일의 자리가 크면 더 큰 수니까","mis":"M2-1-u1-X13"}],"mis":"M2-1-u1-X13","explanation":["백의 자리는 1로 같아요.","십의 자리를 보면 9가 6보다 커서 196이 더 커요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"308과 290 가운데 308이 더 커요.","answer":"O","reason_options":[{"t":"백의 자리 3이 2보다 크니까","correct":true},{"t":"290은 십의 자리 9가 커서 더 크니까","mis":"M2-1-u1-X13"}],"explanation":["백의 자리를 보면 3이 2보다 커요.","그래서 308이 더 커요.","그래서 맞는 말이에요."]},{"stem":"547과 574 가운데 547이 더 커요.","answer":"X","reason_options":[{"t":"십의 자리 4가 7보다 작아서 574가 더 크니까","correct":true},{"t":"일의 자리 7이 4보다 커서 547이 더 크니까","mis":"M2-1-u1-X13"}],"explanation":["백의 자리는 5로 같아요.","십의 자리를 보면 7이 4보다 커서 574가 더 커요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#8','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',2,'blank','auto','635 (        ) 653 — 빈칸에 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u1-X14','M2-1-u1-X13']::text[],true,'{"seq":8,"concept":"M2-1-u1-C6","difficulty":2,"kind":"blank","stem":"635 (        ) 653 — 빈칸에 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M2-1-u1-X14"},{"t":"=","mis":"M2-1-u1-X13"}],"explanation":["백의 자리는 6으로 같아요.","십의 자리를 보면 3이 5보다 작아서 635가 더 작아요.","작은 쪽을 뾰족하게 — 635 < 653이에요."],"variant_rule":{"alt":[{"stem":"802 (        ) 799 — 빈칸에 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M2-1-u1-X14"},{"t":"=","mis":"M2-1-u1-X13"}],"explanation":["백의 자리를 보면 8이 7보다 커요.","그래서 802가 더 커요.","큰 쪽으로 벌어지게 — 802 > 799예요."]},{"stem":"471 (        ) 474 — 빈칸에 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M2-1-u1-X14"},{"t":"=","mis":"M2-1-u1-X13"}],"explanation":["백의 자리와 십의 자리가 같아요.","일의 자리를 보면 1이 4보다 작아요.","그래서 471 < 474예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#9','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',2,'match','auto','두 수 가운데 더 큰 수끼리 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u1-C6","difficulty":2,"kind":"match","stem":"두 수 가운데 더 큰 수끼리 이어 보세요.","pairs":[{"l":"308과 380","r":"380"},{"l":"299와 301","r":"301"},{"l":"751과 715","r":"751"}],"mis":"M2-1-u1-X13","explanation":["308과 380은 십의 자리 8이 커서 380이 커요.","299와 301은 백의 자리 3이 커서 301, 751과 715는 십의 자리 5가 커서 751이에요.","높은 자리부터 차례로 견주어요."],"variant_rule":{"alt":[{"stem":"두 수 가운데 더 작은 수끼리 이어 보세요.","pairs":[{"l":"620과 602","r":"602"},{"l":"199와 200","r":"199"},{"l":"845와 854","r":"845"}],"explanation":["620과 602는 십의 자리 0이 작아서 602가 작아요.","199와 200은 백의 자리 1이 작아서 199, 845와 854는 845예요.","높은 자리부터 차례로 견주어요."]},{"stem":"이번에는 다른 보기예요. 두 수 가운데 더 큰 수끼리 이어 보세요.","pairs":[{"l":"509와 590","r":"590"},{"l":"400과 399","r":"400"},{"l":"263과 236","r":"263"}],"explanation":["509와 590은 십의 자리 9가 커서 590이에요.","400과 399는 백의 자리 4가 커서 400, 263과 236은 263이에요.","높은 자리부터 차례로 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_basic#10','math',2,1,'u1','L07','g2_1_math_u1_L07_basic','lesson_basic','M2-1-u1-C6',3,'mc','auto','곰이는 책을 716권, 펭이는 718권, 토리는 709권 읽었어요. 가장 많이 읽은 친구는 누구인가요?',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":10,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"곰이는 책을 716권, 펭이는 718권, 토리는 709권 읽었어요. 가장 많이 읽은 친구는 누구인가요?","options":[{"t":"펭이","correct":true},{"t":"토리","mis":"M2-1-u1-X13"},{"t":"곰이","mis":"M2-1-u1-X13"}],"explanation":["세 수의 백의 자리는 7로 같아요.","십의 자리는 1·1·0이라 토리가 가장 적고, 716과 718은 일의 자리 8이 커요.","그래서 가장 많이 읽은 친구는 펭이예요."],"variant_rule":{"alt":[{"stem":"하늘이는 줄넘기를 245번, 바다는 254번, 솔이는 239번 했어요. 가장 적게 한 친구는 누구인가요?","options":[{"t":"솔이","correct":true},{"t":"바다","mis":"M2-1-u1-X15"},{"t":"하늘","mis":"M2-1-u1-X13"}],"explanation":["세 수의 백의 자리는 2로 같아요.","십의 자리는 4·5·3이라 솔이가 가장 적어요.","「가장 적게」를 잘 읽어요."]},{"stem":"가게에 사과 312개, 배 321개, 감 302개가 있어요. 가장 많은 과일은 무엇인가요?","options":[{"t":"배","correct":true},{"t":"감","mis":"M2-1-u1-X13"},{"t":"사과","mis":"M2-1-u1-X13"}],"explanation":["세 수의 백의 자리는 3으로 같아요.","십의 자리는 1·2·0이라 배가 가장 많아요.","일의 자리가 아니라 십의 자리부터 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#1','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',2,'mc','auto','378, 412, 387 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],true,'{"seq":1,"concept":"M2-1-u1-C6","difficulty":2,"kind":"mc","stem":"378, 412, 387 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"412","correct":true},{"t":"387","mis":"M2-1-u1-X13"},{"t":"378","mis":"M2-1-u1-X15"}],"explanation":["높은 자리(백의 자리)부터 차례로 견주어요.","가장 큰 수는 412예요.","일의 자리가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp3d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#2','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',2,'mc','auto','수 카드 3, 8, 5를 한 번씩 모두 써서 만들 수 있는 가장 큰 세 자리 수는 무엇인가요?',ARRAY['M2-1-u1-X15','M2-1-u1-X16']::text[],true,'{"seq":2,"concept":"M2-1-u1-C6","difficulty":2,"kind":"mc","stem":"수 카드 3, 8, 5를 한 번씩 모두 써서 만들 수 있는 가장 큰 세 자리 수는 무엇인가요?","options":[{"t":"853","correct":true},{"t":"358","mis":"M2-1-u1-X15"},{"t":"835","mis":"M2-1-u1-X16"}],"explanation":["가장 큰 8을 백의 자리에 놓아요.","남은 카드도 큰 수부터 — 853이에요.","높은 자리일수록 큰 숫자를 놓아요."],"variant_rule":{"cards3":{"ask":"max"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#3','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',3,'mc','auto','수 카드 4, 0, 7을 한 번씩 모두 써서 만들 수 있는 가장 작은 세 자리 수는 무엇인가요?',ARRAY['M2-1-u1-X16','M2-1-u1-X15']::text[],true,'{"seq":3,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 4, 0, 7을 한 번씩 모두 써서 만들 수 있는 가장 작은 세 자리 수는 무엇인가요?","options":[{"t":"407","correct":true},{"t":"47","mis":"M2-1-u1-X16"},{"t":"740","mis":"M2-1-u1-X15"}],"explanation":["0은 백의 자리에 놓을 수 없어요(그러면 두 자리 수).","백의 자리에 4, 십의 자리에 0, 일의 자리에 7 — 407이에요.","0이 있으면 백의 자리 다음 자리에 놓아요."],"variant_rule":{"cards3":{"ask":"min","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#4','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',3,'mc','auto','4□7은 457보다 커요. □에 들어갈 수 있는 가장 작은 수는 무엇인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],true,'{"seq":4,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"4□7은 457보다 커요. □에 들어갈 수 있는 가장 작은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M2-1-u1-X13"},{"t":"0","mis":"M2-1-u1-X15"}],"explanation":["백의 자리는 4로 같으니 십의 자리를 견주어요.","□가 5이면 457과 같아 크지 않아요 — □는 6부터예요.","가장 작은 수는 6이에요."],"variant_rule":{"alt":[{"stem":"6□3은 648보다 작아요. □에 들어갈 수 있는 가장 큰 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-1-u1-X13"},{"t":"9","mis":"M2-1-u1-X15"}],"explanation":["백의 자리는 6으로 같으니 십의 자리를 견주어요.","□가 4이면 643 — 648보다 작아요. □가 5이면 653이라 커요.","그래서 가장 큰 수는 4예요."]},{"stem":"3□5는 362보다 커요. □에 들어갈 수 있는 가장 작은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"7","mis":"M2-1-u1-X13"},{"t":"2","mis":"M2-1-u1-X15"}],"explanation":["백의 자리는 3으로 같으니 십의 자리를 견주어요.","□가 6이면 365 — 362보다 커요.","가장 작은 수는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#5','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',3,'sa','auto','3□5는 325보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?','{}'::text[],true,'{"seq":5,"concept":"M2-1-u1-C6","difficulty":3,"kind":"sa","stem":"3□5는 325보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["2","2개"],"explanation":["백의 자리는 3으로 같으니 십의 자리를 견주어요.","□가 2이면 325와 같아요 — □는 2보다 작은 0과 1이에요.","그래서 모두 2개예요."],"variant_rule":{"alt":[{"stem":"5□0은 560보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["3","3개"],"explanation":["백의 자리는 5로 같으니 십의 자리를 견주어요.","□가 6이면 560과 같아요 — □는 7, 8, 9예요.","그래서 모두 3개예요."]},{"stem":"7□4는 734보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["3","3개"],"explanation":["백의 자리는 7로 같으니 십의 자리를 견주어요.","□가 3이면 734와 같아요 — □는 0, 1, 2예요.","그래서 모두 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#6','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',3,'error','auto','친구들이 두 수를 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X14']::text[],true,'{"seq":6,"concept":"M2-1-u1-C6","difficulty":3,"kind":"error","stem":"친구들이 두 수를 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"도하: 298 > 302 (9가 0보다 크니까)","correct":true,"mis_target":"M2-1-u1-X13"},{"t":"유진: 450 < 504","mis":"M2-1-u1-X14"},{"t":"세아: 671 > 617","mis":"M2-1-u1-X13"}],"explanation":["298과 302는 백의 자리부터 봐요 — 2는 3보다 작아요.","그래서 298 < 302예요.","도하가 잘못 비교했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 두 수를 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"준우: 836 < 829 (백의 자리가 같으니 일의 자리 6이 9보다 작아서)","correct":true,"mis_target":"M2-1-u1-X13"},{"t":"서준: 905 > 899","mis":"M2-1-u1-X13"},{"t":"라희: 712 < 721","mis":"M2-1-u1-X14"}],"explanation":["836과 829는 백의 자리가 같으니 십의 자리를 봐요 — 3이 2보다 커요.","그래서 836 > 829예요.","준우가 잘못 비교했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#7','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',3,'mc','auto','800보다 크고 820보다 작은 수 가운데 일의 자리 숫자가 5인 수는 모두 몇 개인가요?',ARRAY['M2-1-u1-X15','M2-1-u1-X13']::text[],true,'{"seq":7,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"800보다 크고 820보다 작은 수 가운데 일의 자리 숫자가 5인 수는 모두 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"3","mis":"M2-1-u1-X15"},{"t":"1","mis":"M2-1-u1-X13"}],"explanation":["800보다 크고 820보다 작은 수는 801부터 819까지예요.","그 가운데 일의 자리 숫자가 5인 수는 805, 815예요.","그래서 모두 2개 — 825는 820보다 커서 안 돼요."],"variant_rule":{"alt":[{"stem":"400보다 크고 430보다 작은 수 가운데 일의 자리 숫자가 0인 수는 모두 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"3","mis":"M2-1-u1-X15"},{"t":"4","mis":"M2-1-u1-X15"}],"explanation":["400보다 크고 430보다 작은 수는 401부터 429까지예요.","그 가운데 일의 자리 숫자가 0인 수는 410, 420이에요.","400과 430은 들어가지 않아요 — 2개예요."]},{"stem":"300보다 크고 330보다 작은 수 가운데 십의 자리 숫자와 일의 자리 숫자가 같은 수는 모두 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"3","mis":"M2-1-u1-X15"},{"t":"1","mis":"M2-1-u1-X13"}],"explanation":["301부터 329까지 살펴봐요.","십·일의 자리 숫자가 같은 수는 311, 322예요.","300과 333은 범위 밖이에요 — 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#8','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',4,'mc','auto','백의 자리 숫자가 5이고, 십의 자리 숫자가 일의 자리 숫자보다 큰 세 자리 수 가운데 540보다 작은 가장 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],true,'{"seq":8,"concept":"M2-1-u1-C6","difficulty":4,"kind":"mc","stem":"백의 자리 숫자가 5이고, 십의 자리 숫자가 일의 자리 숫자보다 큰 세 자리 수 가운데 540보다 작은 가장 큰 수는 무엇인가요?","options":[{"t":"532","correct":true},{"t":"539","mis":"M2-1-u1-X13"},{"t":"543","mis":"M2-1-u1-X15"}],"explanation":["540보다 작으니 십의 자리 숫자는 3까지예요(54□는 540 이상).","십의 자리가 3이면 일의 자리는 3보다 작아야 해요 — 가장 큰 것은 2예요.","그래서 532예요."],"variant_rule":{"alt":[{"stem":"백의 자리 숫자가 3이고, 일의 자리 숫자가 십의 자리 숫자보다 큰 세 자리 수 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"301","correct":true},{"t":"300","mis":"M2-1-u1-X13"},{"t":"310","mis":"M2-1-u1-X16"}],"explanation":["가장 작은 수는 십의 자리를 0으로 해요.","일의 자리는 0보다 커야 하니 가장 작은 1이에요.","그래서 301이에요."]},{"stem":"백의 자리 숫자가 7이고, 세 자리 숫자가 모두 다른 수 가운데 760보다 큰 가장 작은 수는 무엇인가요?","options":[{"t":"761","correct":true},{"t":"760","mis":"M2-1-u1-X13"},{"t":"770","mis":"M2-1-u1-X16"}],"explanation":["760보다 커야 하니 76□에서 □는 1부터예요.","7, 6, 1은 모두 달라요.","그래서 761이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#9','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',4,'mc','auto','수 카드 6, 0, 2, 9 가운데 세 장을 골라 만들 수 있는 세 자리 수 가운데 500보다 작은 가장 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X15','M2-1-u1-X16']::text[],true,'{"seq":9,"concept":"M2-1-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 6, 0, 2, 9 가운데 세 장을 골라 만들 수 있는 세 자리 수 가운데 500보다 작은 가장 큰 수는 무엇인가요?","options":[{"t":"296","correct":true},{"t":"962","mis":"M2-1-u1-X15"},{"t":"209","mis":"M2-1-u1-X16"}],"explanation":["500보다 작으려면 백의 자리에 6·9는 올 수 없고, 0도 올 수 없어요 — 2예요.","남은 카드 6, 0, 9 가운데 큰 수부터 — 9, 6이에요.","그래서 296이에요."],"variant_rule":{"alt":[{"stem":"수 카드 1, 7, 0, 4 가운데 세 장을 골라 만들 수 있는 세 자리 수 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"104","correct":true},{"t":"14","mis":"M2-1-u1-X16"},{"t":"741","mis":"M2-1-u1-X15"}],"explanation":["0은 백의 자리에 올 수 없어요 — 가장 작은 1을 놓아요.","남은 카드 가운데 작은 0, 4를 차례로 놓아요.","그래서 104예요."]},{"stem":"수 카드 5, 8, 3, 1 가운데 세 장을 골라 만들 수 있는 세 자리 수 가운데 600보다 큰 가장 작은 수는 무엇인가요?","options":[{"t":"813","correct":true},{"t":"583","mis":"M2-1-u1-X15"},{"t":"831","mis":"M2-1-u1-X16"}],"explanation":["600보다 크려면 백의 자리는 8이에요.","남은 카드 가운데 작은 1, 3을 차례로 놓아요.","그래서 813이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_L07_challenge#10','math',2,1,'u1','L07','g2_1_math_u1_L07_challenge','lesson_challenge','M2-1-u1-C6',4,'essay','teacher','479와 497 가운데 더 큰 수를 고르고, 높은 자리부터 비교하는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u1-C6","difficulty":4,"kind":"essay","stem":"479와 497 가운데 더 큰 수를 고르고, 높은 자리부터 비교하는 방법으로 설명해 보세요.","answer_guide":{"answer":"497이 더 크다. 백의 자리는 4로 같고, 십의 자리를 보면 9가 7보다 크므로 497이 더 크다.","scoring_points":["497을 골랐는가","백의 자리가 같다는 것을 말했는가","십의 자리 9와 7을 견주어 설명했는가(일의 자리로 판단하지 않았는가)"]},"explanation":["백의 자리는 둘 다 4예요.","십의 자리를 보면 9가 7보다 커서 497이 더 커요.","일의 자리 9와 7은 볼 필요가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#1','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C1',1,'mc','auto','99보다 1만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X12']::text[],false,'{"seq":1,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"99보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"910","mis":"M2-1-u1-X01"},{"t":"98","mis":"M2-1-u1-X12"}],"explanation":["99 바로 다음 수예요.","99보다 1 큰 수는 100이에요.","9 뒤에 10을 붙이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#2','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C2',1,'mc','auto','100이 5개이면 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":2,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"100이 5개이면 얼마인가요?","options":[{"t":"500","correct":true},{"t":"105","mis":"M2-1-u1-X03"},{"t":"50","mis":"M2-1-u1-X03"}],"explanation":["100이 5개이면 500이에요.","「오백」이라고 읽어요.","개수는 백의 자리에 쓰고, 십·일의 자리는 0이에요."],"variant_rule":{"n3":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#3','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X06','M2-1-u1-X05']::text[],true,'{"seq":3,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"247","correct":true},{"t":"742","mis":"M2-1-u1-X06"},{"t":"200407","mis":"M2-1-u1-X05"}],"explanation":["100이 2개, 10이 4개, 1이 7개예요.","백의 자리 2, 십의 자리 4, 일의 자리 7 — 247이에요.","백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks3","h":2,"t":4,"o":7},"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#4','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-1-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"527","r":"오백이십칠"},{"l":"507","r":"오백칠"},{"l":"570","r":"오백칠십"}],"mis":"M2-1-u1-X07","explanation":["527은 「오백이십칠」이에요.","507은 「오백칠」, 570은 「오백칠십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#5','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C4',1,'mc','auto','482에서 십의 자리 숫자는 무엇인가요?',ARRAY['M2-1-u1-X08','M2-1-u1-X09']::text[],true,'{"seq":5,"concept":"M2-1-u1-C4","difficulty":1,"kind":"mc","stem":"482에서 십의 자리 숫자는 무엇인가요?","options":[{"t":"8","correct":true},{"t":"2","mis":"M2-1-u1-X08"},{"t":"80","mis":"M2-1-u1-X09"}],"explanation":["482는 백의 자리 4, 십의 자리 8, 일의 자리 2예요.","십의 자리 숫자는 8이에요.","자리는 왼쪽부터 백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv3":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#6','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C5',1,'mc','auto','100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":6,"concept":"M2-1-u1-C5","difficulty":1,"kind":"mc","stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"650","correct":true},{"t":"551","mis":"M2-1-u1-X11"},{"t":"560","mis":"M2-1-u1-X11"}],"explanation":["100씩 뛰면 백의 자리 숫자가 1씩 커져요.","550에서 100만큼 뛰면 650이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[250,350,450,550,null],"step":100},"variant_rule":{"skip3":{"ask":"next","step":[100]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#7','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C6',1,'mc','auto','638과 683 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":7,"concept":"M2-1-u1-C6","difficulty":1,"kind":"mc","stem":"638과 683 중에서 더 큰 수는 무엇인가요?","options":[{"t":"683","correct":true},{"t":"638","mis":"M2-1-u1-X13"}],"explanation":["백의 자리가 같아요.","십의 자리를 보면 8은 3보다 커요 — 더 큰 수는 683이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp3d":{"ask":"big","same":"h"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#8','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C2',1,'sa','auto','600은 100이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-1-u1-C2","difficulty":1,"kind":"sa","stem":"600은 100이 몇 개인가요?","answer":["6","6개"],"explanation":["600은 백의 자리 숫자가 6이에요.","100이 6개예요.","백의 자리 숫자가 100의 개수예요."],"variant_rule":{"n3":{"ask":"hcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#9','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C1',2,'blank','auto','100은 90보다 (        )만큼 더 큰 수예요.',ARRAY['M2-1-u1-X12']::text[],false,'{"seq":9,"concept":"M2-1-u1-C1","difficulty":2,"kind":"blank","stem":"100은 90보다 (        )만큼 더 큰 수예요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X12"},{"t":"100","mis":"M2-1-u1-X12"}],"explanation":["90 다음 10씩 뛰면 100이에요.","그래서 100은 90보다 10 커요.","십 모형 1개 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#10','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C3',2,'mc','auto','「사백구」를 수로 쓰면 무엇인가요?',ARRAY['M2-1-u1-X05','M2-1-u1-X04']::text[],true,'{"seq":10,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"「사백구」를 수로 쓰면 무엇인가요?","options":[{"t":"409","correct":true},{"t":"4009","mis":"M2-1-u1-X05"},{"t":"49","mis":"M2-1-u1-X04"}],"explanation":["「사백구」는 100이 4개, 10이 0개, 1이 9개예요.","수로 쓰면 409예요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n3":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#11','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C4',2,'mc','auto','947에서 숫자 4가 나타내는 값은 얼마인가요?',ARRAY['M2-1-u1-X08','M2-1-u1-X09']::text[],true,'{"seq":11,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"947에서 숫자 4가 나타내는 값은 얼마인가요?","options":[{"t":"40","correct":true},{"t":"400","mis":"M2-1-u1-X08"},{"t":"4","mis":"M2-1-u1-X09"}],"explanation":["숫자 4는 십의 자리에 있어요.","십의 자리 4는 40을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv3":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#12','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C4',2,'mc','auto','374를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X08']::text[],true,'{"seq":12,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"374를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"300 + 70 + 4","correct":true},{"t":"3 + 7 + 4","mis":"M2-1-u1-X09"},{"t":"300 + 40 + 7","mis":"M2-1-u1-X08"}],"explanation":["374는 백의 자리 3, 십의 자리 7, 일의 자리 4예요.","각 자리의 값은 300, 70, 4 — 374 = 300 + 70 + 4.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv3":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#13','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C5',2,'mc','auto','얼마씩 뛰어 세었나요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":13,"concept":"M2-1-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 뛰어 세었나요?","options":[{"t":"10씩","correct":true},{"t":"1씩","mis":"M2-1-u1-X12"},{"t":"100씩","mis":"M2-1-u1-X12"}],"explanation":["520, 530, 540 … 하고 십의 자리 숫자만 1씩 커져요.","그래서 10씩 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[520,530,540,550,560],"step":null},"variant_rule":{"skip3":{"ask":"step","step":[1,10,100],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#14','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-1-u1-X14']::text[],true,'{"seq":14,"concept":"M2-1-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"603 > 598","correct":true},{"t":"603 < 598","mis":"M2-1-u1-X14"}],"explanation":["백의 자리에서 처음으로 달라요 — 6은 5보다 커요.","그래서 603은 598보다 커요 — 603 > 598.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp3d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#15','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C2',2,'error','auto','친구들이 몇백에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u1-X03','M2-1-u1-X07','M2-1-u1-X12']::text[],false,'{"seq":15,"concept":"M2-1-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇백에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우: 700은 100이 70개야.","correct":true,"mis_target":"M2-1-u1-X03"},{"t":"하린: 700은 「칠백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"도윤: 700은 600보다 100 큰 수야.","mis":"M2-1-u1-X12"}],"explanation":["700은 백의 자리 숫자가 7이에요.","그래서 100이 7개예요 — 70개가 아니에요.","은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#16','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C7',2,'mc','auto','10이 23개인 수는 얼마인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X10']::text[],true,'{"seq":16,"concept":"M2-1-u1-C7","difficulty":2,"kind":"mc","stem":"10이 23개인 수는 얼마인가요?","options":[{"t":"230","correct":true},{"t":"1023","mis":"M2-1-u1-X02"},{"t":"23","mis":"M2-1-u1-X10"}],"explanation":["10이 10개면 100이에요.","10이 23개는 100이 2개, 10이 3개 — 230이에요.","10이 10개 넘게 모이면 100으로 바꿔 세요."],"variant_rule":{"n3":{"ask":"tens"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#17','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C5',3,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X11']::text[],true,'{"seq":17,"concept":"M2-1-u1-C5","difficulty":3,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"400","correct":true},{"t":"3100","mis":"M2-1-u1-X01"},{"t":"391","mis":"M2-1-u1-X11"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","390에서 10만큼 뛰면 400이에요.","십의 자리가 10이 되면 바로 윗자리가 1 커지고 십의 자리는 0이 돼요."],"asset":{"type":"jump_row","cells":[370,380,390,null,410],"step":10},"variant_rule":{"skip3":{"ask":"blank","step":[10],"cross":true,"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#18','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C6',3,'mc','auto','496, 512, 469 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],true,'{"seq":18,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"496, 512, 469 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"512","correct":true},{"t":"496","mis":"M2-1-u1-X13"},{"t":"469","mis":"M2-1-u1-X15"}],"explanation":["높은 자리(백의 자리)부터 차례로 견주어요.","가장 큰 수는 512예요.","일의 자리가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp3d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#19','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C7',3,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":19,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"334원","correct":true},{"t":"2134원","mis":"M2-1-u1-X10"},{"t":"234원","mis":"M2-1-u1-X10"}],"explanation":["10원짜리 13개는 100원짜리 1개와 10원짜리 3개로 바꿀 수 있어요.","100원짜리 3개, 10원짜리 3개, 1원짜리 4개 — 334원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":2,"t":13,"o":4,"unit":"coin"},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#20','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":20,"concept":"M2-1-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"226","correct":true},{"t":"1126","mis":"M2-1-u1-X10"},{"t":"126","mis":"M2-1-u1-X10"}],"explanation":["십 모형 12개는 백 모형 1개와 십 모형 2개로 바꿀 수 있어요.","100이 2개, 10이 2개, 1이 6개 — 226이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":1,"t":12,"o":6},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#21','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C4',3,'ox','auto','737에서 두 숫자 7이 나타내는 값은 같아요.',ARRAY['M2-1-u1-X09']::text[],false,'{"seq":21,"concept":"M2-1-u1-C4","difficulty":3,"kind":"ox","stem":"737에서 두 숫자 7이 나타내는 값은 같아요.","answer":"X","reason_options":[{"t":"앞의 7은 700, 뒤의 7은 7이니까","correct":true},{"t":"같은 숫자는 값도 같으니까","mis":"M2-1-u1-X09"}],"mis":"M2-1-u1-X09","explanation":["앞의 7은 백의 자리라 700이에요.","뒤의 7은 일의 자리라 7이에요.","그래서 틀린 말이에요 — 자리에 따라 값이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#22','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C6',3,'mc','auto','수 카드 2, 9, 6을 한 번씩 모두 써서 만들 수 있는 가장 큰 세 자리 수는 무엇인가요?',ARRAY['M2-1-u1-X15','M2-1-u1-X16']::text[],true,'{"seq":22,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 2, 9, 6을 한 번씩 모두 써서 만들 수 있는 가장 큰 세 자리 수는 무엇인가요?","options":[{"t":"962","correct":true},{"t":"269","mis":"M2-1-u1-X15"},{"t":"926","mis":"M2-1-u1-X16"}],"explanation":["가장 큰 9를 백의 자리에 놓아요.","남은 카드도 큰 수부터 — 962예요.","높은 자리일수록 큰 숫자를 놓아요."],"variant_rule":{"cards3":{"ask":"max"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#23','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C7',4,'mc','auto','100원짜리 동전 3개와 10원짜리 동전 4개를 모두 10원짜리 동전으로 바꾸면 몇 개가 되나요?',ARRAY['M2-1-u1-X03','M2-1-u1-X04']::text[],false,'{"seq":23,"concept":"M2-1-u1-C7","difficulty":4,"kind":"mc","stem":"100원짜리 동전 3개와 10원짜리 동전 4개를 모두 10원짜리 동전으로 바꾸면 몇 개가 되나요?","options":[{"t":"34","correct":true},{"t":"7","mis":"M2-1-u1-X03"},{"t":"304","mis":"M2-1-u1-X04"}],"explanation":["100원짜리 하나는 10원짜리 10개예요.","100원짜리 3개는 10원짜리 30개 — 4개를 더하면 34개예요.","340원은 10이 34개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#24','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C6',4,'mc','auto','5□3은 567보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],false,'{"seq":24,"concept":"M2-1-u1-C6","difficulty":4,"kind":"mc","stem":"5□3은 567보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u1-X13"},{"t":"6","mis":"M2-1-u1-X15"}],"explanation":["백의 자리는 5로 같으니 십의 자리를 견주어요.","□가 6이면 563 — 567보다 작아요. □는 7, 8, 9예요.","그래서 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_a#25','math',2,1,'u1','','g2_1_math_u1_review_a','unit_review','M2-1-u1-C5',4,'essay','teacher','395부터 1씩 7번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u1-C5","difficulty":4,"kind":"essay","stem":"395부터 1씩 7번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"396, 397, 398, 399, 400, 401, 402. 399 다음에 일의 자리가 10이 되어 십의 자리로, 십의 자리도 10이 되어 백의 자리로 넘어가 400이 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#1','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C1',1,'mc','auto','90보다 10만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X12','M2-1-u1-X01']::text[],false,'{"seq":1,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"90보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"91","mis":"M2-1-u1-X12"},{"t":"9010","mis":"M2-1-u1-X01"}],"explanation":["90에서 10을 더 뛰어요.","90보다 10 큰 수는 100이에요.","10만큼과 1만큼을 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#2','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C2',1,'mc','auto','100이 7개이면 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":2,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"100이 7개이면 얼마인가요?","options":[{"t":"700","correct":true},{"t":"107","mis":"M2-1-u1-X03"},{"t":"70","mis":"M2-1-u1-X03"}],"explanation":["100이 7개이면 700이에요.","「칠백」이라고 읽어요.","개수는 백의 자리에 쓰고, 십·일의 자리는 0이에요."],"variant_rule":{"n3":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#3','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X06','M2-1-u1-X05']::text[],true,'{"seq":3,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"361","correct":true},{"t":"163","mis":"M2-1-u1-X06"},{"t":"300601","mis":"M2-1-u1-X05"}],"explanation":["100이 3개, 10이 6개, 1이 1개예요.","백의 자리 3, 십의 자리 6, 일의 자리 1 — 361이에요.","백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks3","h":3,"t":6,"o":1},"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#4','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-1-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"318","r":"삼백십팔"},{"l":"308","r":"삼백팔"},{"l":"380","r":"삼백팔십"}],"mis":"M2-1-u1-X07","explanation":["318은 「삼백십팔」이에요.","308은 「삼백팔」, 380은 「삼백팔십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#5','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C4',1,'mc','auto','736에서 백의 자리 숫자는 무엇인가요?',ARRAY['M2-1-u1-X08','M2-1-u1-X09']::text[],true,'{"seq":5,"concept":"M2-1-u1-C4","difficulty":1,"kind":"mc","stem":"736에서 백의 자리 숫자는 무엇인가요?","options":[{"t":"7","correct":true},{"t":"6","mis":"M2-1-u1-X08"},{"t":"700","mis":"M2-1-u1-X09"}],"explanation":["736은 백의 자리 7, 십의 자리 3, 일의 자리 6이에요.","백의 자리 숫자는 7이에요.","자리는 왼쪽부터 백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv3":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#6','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C5',1,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":6,"concept":"M2-1-u1-C5","difficulty":1,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"653","correct":true},{"t":"644","mis":"M2-1-u1-X11"},{"t":"743","mis":"M2-1-u1-X11"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","643에서 10만큼 뛰면 653이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[613,623,633,643,null],"step":10},"variant_rule":{"skip3":{"ask":"next","step":[10]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#7','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C6',1,'mc','auto','471과 417 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":7,"concept":"M2-1-u1-C6","difficulty":1,"kind":"mc","stem":"471과 417 중에서 더 큰 수는 무엇인가요?","options":[{"t":"471","correct":true},{"t":"417","mis":"M2-1-u1-X13"}],"explanation":["백의 자리가 같아요.","십의 자리를 보면 7은 1보다 커요 — 더 큰 수는 471이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp3d":{"ask":"big","same":"h"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#8','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C2',1,'sa','auto','400은 100이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-1-u1-C2","difficulty":1,"kind":"sa","stem":"400은 100이 몇 개인가요?","answer":["4","4개"],"explanation":["400은 백의 자리 숫자가 4예요.","100이 4개예요.","백의 자리 숫자가 100의 개수예요."],"variant_rule":{"n3":{"ask":"hcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#9','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C1',2,'blank','auto','100은 99보다 (        )만큼 더 큰 수예요.',ARRAY['M2-1-u1-X12']::text[],false,'{"seq":9,"concept":"M2-1-u1-C1","difficulty":2,"kind":"blank","stem":"100은 99보다 (        )만큼 더 큰 수예요.","options":[{"t":"1","correct":true},{"t":"10","mis":"M2-1-u1-X12"},{"t":"100","mis":"M2-1-u1-X12"}],"explanation":["99 바로 다음 수가 100이에요.","그래서 100은 99보다 1 커요.","바로 다음 수는 1 큰 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#10','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C3',2,'mc','auto','「팔백육십」을 수로 쓰면 무엇인가요?',ARRAY['M2-1-u1-X05','M2-1-u1-X04']::text[],true,'{"seq":10,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"「팔백육십」을 수로 쓰면 무엇인가요?","options":[{"t":"860","correct":true},{"t":"80060","mis":"M2-1-u1-X05"},{"t":"86","mis":"M2-1-u1-X04"}],"explanation":["「팔백육십」은 100이 8개, 10이 6개, 1이 0개예요.","수로 쓰면 860이에요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n3":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#11','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C4',2,'mc','auto','263에서 숫자 2가 나타내는 값은 얼마인가요?',ARRAY['M2-1-u1-X08','M2-1-u1-X09']::text[],true,'{"seq":11,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"263에서 숫자 2가 나타내는 값은 얼마인가요?","options":[{"t":"200","correct":true},{"t":"20","mis":"M2-1-u1-X08"},{"t":"2","mis":"M2-1-u1-X09"}],"explanation":["숫자 2는 백의 자리에 있어요.","백의 자리 2는 200을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv3":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#12','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C4',2,'mc','auto','528을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X08']::text[],true,'{"seq":12,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"528을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"500 + 20 + 8","correct":true},{"t":"5 + 2 + 8","mis":"M2-1-u1-X09"},{"t":"500 + 80 + 2","mis":"M2-1-u1-X08"}],"explanation":["528은 백의 자리 5, 십의 자리 2, 일의 자리 8이에요.","각 자리의 값은 500, 20, 8 — 528 = 500 + 20 + 8.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv3":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#13','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C5',2,'mc','auto','얼마씩 거꾸로 뛰어 세었나요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":13,"concept":"M2-1-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 거꾸로 뛰어 세었나요?","options":[{"t":"100씩","correct":true},{"t":"1씩","mis":"M2-1-u1-X12"},{"t":"10씩","mis":"M2-1-u1-X12"}],"explanation":["815, 715, 615 … 하고 백의 자리 숫자만 1씩 작아져요.","그래서 100씩 거꾸로 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[815,715,615,515,415],"step":null,"dir":"down"},"variant_rule":{"skip3":{"ask":"step","step":[1,10,100],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#14','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-1-u1-X14']::text[],true,'{"seq":14,"concept":"M2-1-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"472 > 427","correct":true},{"t":"472 < 427","mis":"M2-1-u1-X14"}],"explanation":["십의 자리에서 처음으로 달라요 — 7은 2보다 커요.","그래서 472는 427보다 커요 — 472 > 427.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp3d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#15','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C2',2,'error','auto','친구들이 몇백에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u1-X03','M2-1-u1-X07','M2-1-u1-X12']::text[],false,'{"seq":15,"concept":"M2-1-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇백에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 100이 4개이면 104야.","correct":true,"mis_target":"M2-1-u1-X03"},{"t":"준우: 400은 「사백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"라희: 400은 300보다 100 큰 수야.","mis":"M2-1-u1-X12"}],"explanation":["100이 4개이면 400이에요.","개수를 일의 자리에 붙여 104로 쓰지 않아요.","서아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#16','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C7',2,'mc','auto','10이 31개인 수는 얼마인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X10']::text[],true,'{"seq":16,"concept":"M2-1-u1-C7","difficulty":2,"kind":"mc","stem":"10이 31개인 수는 얼마인가요?","options":[{"t":"310","correct":true},{"t":"1031","mis":"M2-1-u1-X02"},{"t":"31","mis":"M2-1-u1-X10"}],"explanation":["10이 10개면 100이에요.","10이 31개는 100이 3개, 10이 1개 — 310이에요.","10이 10개 넘게 모이면 100으로 바꿔 세요."],"variant_rule":{"n3":{"ask":"tens"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#17','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C5',3,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X11']::text[],true,'{"seq":17,"concept":"M2-1-u1-C5","difficulty":3,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"600","correct":true},{"t":"5910","mis":"M2-1-u1-X01"},{"t":"609","mis":"M2-1-u1-X11"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","599에서 1만큼 뛰면 600이에요.","일의 자리가 10이 되면 바로 윗자리가 1 커지고 일의 자리는 0이 돼요."],"asset":{"type":"jump_row","cells":[598,599,null,601,602],"step":1},"variant_rule":{"skip3":{"ask":"blank","step":[1],"cross":true,"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#18','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C6',3,'mc','auto','318, 402, 491 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],true,'{"seq":18,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"318, 402, 491 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"318","correct":true},{"t":"402","mis":"M2-1-u1-X13"},{"t":"491","mis":"M2-1-u1-X15"}],"explanation":["높은 자리(백의 자리)부터 차례로 견주어요.","가장 작은 수는 318이에요.","일의 자리가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp3d":{"ask":"min3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#19','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C7',3,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":19,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"366원","correct":true},{"t":"3516원","mis":"M2-1-u1-X10"},{"t":"356원","mis":"M2-1-u1-X10"}],"explanation":["1원짜리 16개는 10원짜리 1개와 1원짜리 6개로 바꿀 수 있어요.","100원짜리 3개, 10원짜리 6개, 1원짜리 6개 — 366원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":3,"t":5,"o":16,"unit":"coin"},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#20','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":20,"concept":"M2-1-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"355","correct":true},{"t":"3415","mis":"M2-1-u1-X10"},{"t":"345","mis":"M2-1-u1-X10"}],"explanation":["일 모형 15개는 십 모형 1개와 일 모형 5개로 바꿀 수 있어요.","100이 3개, 10이 5개, 1이 5개 — 355예요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":3,"t":4,"o":15},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#21','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C4',3,'ox','auto','191에서 두 숫자 1이 나타내는 값은 100과 1이에요.',ARRAY['M2-1-u1-X09']::text[],false,'{"seq":21,"concept":"M2-1-u1-C4","difficulty":3,"kind":"ox","stem":"191에서 두 숫자 1이 나타내는 값은 100과 1이에요.","answer":"O","reason_options":[{"t":"백의 자리 1은 100, 일의 자리 1은 1이니까","correct":true},{"t":"같은 숫자는 값도 같으니까","mis":"M2-1-u1-X09"}],"mis":"M2-1-u1-X09","explanation":["앞의 1은 백의 자리라 100이에요.","뒤의 1은 일의 자리라 1이에요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#22','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C6',3,'mc','auto','수 카드 5, 0, 3을 한 번씩 모두 써서 만들 수 있는 가장 작은 세 자리 수는 무엇인가요?',ARRAY['M2-1-u1-X16','M2-1-u1-X15']::text[],true,'{"seq":22,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 5, 0, 3을 한 번씩 모두 써서 만들 수 있는 가장 작은 세 자리 수는 무엇인가요?","options":[{"t":"305","correct":true},{"t":"35","mis":"M2-1-u1-X16"},{"t":"530","mis":"M2-1-u1-X15"}],"explanation":["0은 백의 자리에 놓을 수 없어요(그러면 두 자리 수).","백의 자리에 3, 십의 자리에 0, 일의 자리에 5 — 305예요.","0이 있으면 백의 자리 다음 자리에 놓아요."],"variant_rule":{"cards3":{"ask":"min","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#23','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C7',4,'mc','auto','100원짜리 동전 2개를 모두 10원짜리 동전으로 바꾸면 몇 개가 되나요?',ARRAY['M2-1-u1-X02','M2-1-u1-X09']::text[],false,'{"seq":23,"concept":"M2-1-u1-C7","difficulty":4,"kind":"mc","stem":"100원짜리 동전 2개를 모두 10원짜리 동전으로 바꾸면 몇 개가 되나요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M2-1-u1-X02"},{"t":"200","mis":"M2-1-u1-X09"}],"explanation":["100원짜리 하나는 10원짜리 10개예요.","100원짜리 2개는 10원짜리 20개예요.","200원은 10이 20개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#24','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C6',4,'mc','auto','□28은 432보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요? (□에는 1부터 9까지)',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],false,'{"seq":24,"concept":"M2-1-u1-C6","difficulty":4,"kind":"mc","stem":"□28은 432보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요? (□에는 1부터 9까지)","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-1-u1-X13"},{"t":"5","mis":"M2-1-u1-X15"}],"explanation":["□가 4이면 428 — 432보다 작아요.","□가 5부터는 커요. □는 1, 2, 3, 4예요.","그래서 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_b#25','math',2,1,'u1','','g2_1_math_u1_review_b','unit_review','M2-1-u1-C5',4,'essay','teacher','960부터 10씩 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u1-C5","difficulty":4,"kind":"essay","stem":"960부터 10씩 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"970, 980, 990, 1000. 990 다음에 십의 자리가 10이 되어 백의 자리로, 백의 자리도 10이 되어 천의 자리로 넘어가 1000이 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#1','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C1',1,'mc','auto','10이 10개인 수는 무엇인가요?',ARRAY['M2-1-u1-X02']::text[],false,'{"seq":1,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"10이 10개인 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"1010","mis":"M2-1-u1-X02"},{"t":"20","mis":"M2-1-u1-X02"}],"explanation":["10씩 10번 세어요.","10이 10개이면 100이에요.","10을 늘어놓아 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#2','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C2',1,'mc','auto','100이 3개이면 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":2,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"100이 3개이면 얼마인가요?","options":[{"t":"300","correct":true},{"t":"103","mis":"M2-1-u1-X03"},{"t":"30","mis":"M2-1-u1-X03"}],"explanation":["100이 3개이면 300이에요.","「삼백」이라고 읽어요.","개수는 백의 자리에 쓰고, 십·일의 자리는 0이에요."],"variant_rule":{"n3":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#3','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X06','M2-1-u1-X05']::text[],true,'{"seq":3,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"528","correct":true},{"t":"825","mis":"M2-1-u1-X06"},{"t":"500208","mis":"M2-1-u1-X05"}],"explanation":["100이 5개, 10이 2개, 1이 8개예요.","백의 자리 5, 십의 자리 2, 일의 자리 8 — 528이에요.","백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks3","h":5,"t":2,"o":8},"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#4','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-1-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"649","r":"육백사십구"},{"l":"609","r":"육백구"},{"l":"690","r":"육백구십"}],"mis":"M2-1-u1-X07","explanation":["649는 「육백사십구」예요.","609는 「육백구」, 690은 「육백구십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#5','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C4',1,'mc','auto','159에서 일의 자리 숫자는 무엇인가요?',ARRAY['M2-1-u1-X08']::text[],true,'{"seq":5,"concept":"M2-1-u1-C4","difficulty":1,"kind":"mc","stem":"159에서 일의 자리 숫자는 무엇인가요?","options":[{"t":"9","correct":true},{"t":"1","mis":"M2-1-u1-X08"},{"t":"5","mis":"M2-1-u1-X08"}],"explanation":["159는 백의 자리 1, 십의 자리 5, 일의 자리 9예요.","일의 자리 숫자는 9예요.","자리는 왼쪽부터 백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv3":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#6','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C5',1,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":6,"concept":"M2-1-u1-C5","difficulty":1,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"388","correct":true},{"t":"397","mis":"M2-1-u1-X11"},{"t":"487","mis":"M2-1-u1-X11"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","387에서 1만큼 뛰면 388이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[384,385,386,387,null],"step":1},"variant_rule":{"skip3":{"ask":"next","step":[1]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#7','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C6',1,'mc','auto','925와 952 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":7,"concept":"M2-1-u1-C6","difficulty":1,"kind":"mc","stem":"925와 952 중에서 더 큰 수는 무엇인가요?","options":[{"t":"952","correct":true},{"t":"925","mis":"M2-1-u1-X13"}],"explanation":["백의 자리가 같아요.","십의 자리를 보면 5는 2보다 커요 — 더 큰 수는 952예요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp3d":{"ask":"big","same":"h"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#8','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C2',1,'sa','auto','800은 100이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-1-u1-C2","difficulty":1,"kind":"sa","stem":"800은 100이 몇 개인가요?","answer":["8","8개"],"explanation":["800은 백의 자리 숫자가 8이에요.","100이 8개예요.","백의 자리 숫자가 100의 개수예요."],"variant_rule":{"n3":{"ask":"hcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#9','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C1',2,'blank','auto','100은 10이 (        )개인 수예요.',ARRAY['M2-1-u1-X02','M2-1-u1-X09']::text[],false,'{"seq":9,"concept":"M2-1-u1-C1","difficulty":2,"kind":"blank","stem":"100은 10이 (        )개인 수예요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-1-u1-X02"},{"t":"100","mis":"M2-1-u1-X09"}],"explanation":["10씩 세어 100까지 가요.","10번 세면 100이에요.","그래서 10이 10개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#10','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C3',2,'mc','auto','「칠백이」를 수로 쓰면 무엇인가요?',ARRAY['M2-1-u1-X05','M2-1-u1-X04']::text[],true,'{"seq":10,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"「칠백이」를 수로 쓰면 무엇인가요?","options":[{"t":"702","correct":true},{"t":"7002","mis":"M2-1-u1-X05"},{"t":"72","mis":"M2-1-u1-X04"}],"explanation":["「칠백이」는 100이 7개, 10이 0개, 1이 2개예요.","수로 쓰면 702예요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n3":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#11','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C4',2,'mc','auto','518에서 숫자 8이 나타내는 값은 얼마인가요?',ARRAY['M2-1-u1-X08']::text[],true,'{"seq":11,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"518에서 숫자 8이 나타내는 값은 얼마인가요?","options":[{"t":"8","correct":true},{"t":"800","mis":"M2-1-u1-X08"},{"t":"80","mis":"M2-1-u1-X08"}],"explanation":["숫자 8은 일의 자리에 있어요.","일의 자리 8은 8을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv3":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#12','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C4',2,'mc','auto','961을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X08']::text[],true,'{"seq":12,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"961을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"900 + 60 + 1","correct":true},{"t":"9 + 6 + 1","mis":"M2-1-u1-X09"},{"t":"900 + 10 + 6","mis":"M2-1-u1-X08"}],"explanation":["961은 백의 자리 9, 십의 자리 6, 일의 자리 1이에요.","각 자리의 값은 900, 60, 1 — 961 = 900 + 60 + 1.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv3":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#13','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C5',2,'mc','auto','얼마씩 뛰어 세었나요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":13,"concept":"M2-1-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 뛰어 세었나요?","options":[{"t":"1씩","correct":true},{"t":"10씩","mis":"M2-1-u1-X12"},{"t":"100씩","mis":"M2-1-u1-X12"}],"explanation":["347, 348, 349 … 하고 일의 자리 숫자만 1씩 커져요.","그래서 1씩 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[347,348,349,350,351],"step":null},"variant_rule":{"skip3":{"ask":"step","step":[1,10,100],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#14','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-1-u1-X14']::text[],true,'{"seq":14,"concept":"M2-1-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"815 < 851","correct":true},{"t":"815 > 851","mis":"M2-1-u1-X14"}],"explanation":["십의 자리에서 처음으로 달라요 — 5는 1보다 커요.","그래서 851은 815보다 커요 — 815 < 851.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp3d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#15','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C2',2,'error','auto','친구들이 몇백에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u1-X03','M2-1-u1-X07','M2-1-u1-X12']::text[],false,'{"seq":15,"concept":"M2-1-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇백에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호: 100이 8개이면 80이야.","correct":true,"mis_target":"M2-1-u1-X03"},{"t":"하윤: 800은 「팔백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"시우: 800은 900보다 100 작은 수야.","mis":"M2-1-u1-X12"}],"explanation":["100이 8개이면 800이에요.","80은 10이 8개인 수예요.","지호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#16','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C7',2,'mc','auto','10이 17개인 수는 얼마인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X10']::text[],true,'{"seq":16,"concept":"M2-1-u1-C7","difficulty":2,"kind":"mc","stem":"10이 17개인 수는 얼마인가요?","options":[{"t":"170","correct":true},{"t":"1017","mis":"M2-1-u1-X02"},{"t":"17","mis":"M2-1-u1-X10"}],"explanation":["10이 10개면 100이에요.","10이 17개는 100이 1개, 10이 7개 — 170이에요.","10이 10개 넘게 모이면 100으로 바꿔 세요."],"variant_rule":{"n3":{"ask":"tens"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#17','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C5',3,'mc','auto','10씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X11']::text[],true,'{"seq":17,"concept":"M2-1-u1-C5","difficulty":3,"kind":"mc","stem":"10씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"490","correct":true},{"t":"590","mis":"M2-1-u1-X01"},{"t":"499","mis":"M2-1-u1-X11"}],"explanation":["10씩 거꾸로 뛰면 십의 자리 숫자가 1씩 작아져요.","500에서 10만큼 거꾸로 뛰면 490이에요.","십의 자리가 0에서 더 작아지면 바로 윗자리에서 1을 빌려 와요."],"asset":{"type":"jump_row","cells":[520,510,500,null,480],"step":10,"dir":"down"},"variant_rule":{"skip3":{"ask":"blank","step":[10],"cross":true,"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#18','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C6',3,'mc','auto','750, 699, 657 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],true,'{"seq":18,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"750, 699, 657 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"750","correct":true},{"t":"699","mis":"M2-1-u1-X13"},{"t":"657","mis":"M2-1-u1-X15"}],"explanation":["높은 자리(백의 자리)부터 차례로 견주어요.","가장 큰 수는 750이에요.","일의 자리가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp3d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#19','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C7',3,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":19,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"240원","correct":true},{"t":"1140원","mis":"M2-1-u1-X10"},{"t":"140원","mis":"M2-1-u1-X10"}],"explanation":["10원짜리 14개는 100원짜리 1개와 10원짜리 4개로 바꿀 수 있어요.","100원짜리 2개, 10원짜리 4개, 1원짜리 0개 — 240원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":1,"t":14,"o":0,"unit":"coin"},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#20','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":20,"concept":"M2-1-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"313","correct":true},{"t":"2113","mis":"M2-1-u1-X10"},{"t":"213","mis":"M2-1-u1-X10"}],"explanation":["십 모형 11개는 백 모형 1개와 십 모형 1개로 바꿀 수 있어요.","100이 3개, 10이 1개, 1이 3개 — 313이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":2,"t":11,"o":3},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#21','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C4',3,'ox','auto','858에서 두 숫자 8이 나타내는 값을 모으면 16이에요.',ARRAY['M2-1-u1-X09']::text[],false,'{"seq":21,"concept":"M2-1-u1-C4","difficulty":3,"kind":"ox","stem":"858에서 두 숫자 8이 나타내는 값을 모으면 16이에요.","answer":"X","reason_options":[{"t":"800과 8을 모으면 808이니까","correct":true},{"t":"8과 8을 모으면 16이니까","mis":"M2-1-u1-X09"}],"mis":"M2-1-u1-X09","explanation":["앞의 8은 800, 뒤의 8은 8을 나타내요.","800과 8을 모으면 808이에요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#22','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C6',3,'mc','auto','수 카드 7, 1, 4를 한 번씩 모두 써서 만들 수 있는 가장 작은 세 자리 수는 무엇인가요?',ARRAY['M2-1-u1-X16','M2-1-u1-X15']::text[],true,'{"seq":22,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 7, 1, 4를 한 번씩 모두 써서 만들 수 있는 가장 작은 세 자리 수는 무엇인가요?","options":[{"t":"147","correct":true},{"t":"174","mis":"M2-1-u1-X16"},{"t":"741","mis":"M2-1-u1-X15"}],"explanation":["가장 작은 1을 백의 자리에 놓아요.","남은 카드도 작은 수부터 — 147이에요.","높은 자리일수록 작은 숫자를 놓아요."],"variant_rule":{"cards3":{"ask":"min"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#23','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C7',4,'mc','auto','10원짜리 동전 47개를 100원짜리와 10원짜리로 바꾸어 동전 수를 가장 적게 하면 동전은 모두 몇 개인가요?',ARRAY['M2-1-u1-X10','M2-1-u1-X15']::text[],false,'{"seq":23,"concept":"M2-1-u1-C7","difficulty":4,"kind":"mc","stem":"10원짜리 동전 47개를 100원짜리와 10원짜리로 바꾸어 동전 수를 가장 적게 하면 동전은 모두 몇 개인가요?","options":[{"t":"11","correct":true},{"t":"47","mis":"M2-1-u1-X10"},{"t":"4","mis":"M2-1-u1-X15"}],"explanation":["10원짜리 47개는 470원 — 100원짜리 4개와 10원짜리 7개로 바꿀 수 있어요.","동전은 4개와 7개, 모두 11개예요.","묻는 것은 동전 「모두」의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#24','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C6',4,'mc','auto','7□9는 739보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],false,'{"seq":24,"concept":"M2-1-u1-C6","difficulty":4,"kind":"mc","stem":"7□9는 739보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u1-X13"},{"t":"6","mis":"M2-1-u1-X15"}],"explanation":["백의 자리는 7로 같으니 십의 자리를 견주어요.","□가 3이면 739와 같아요. □는 0, 1, 2예요.","그래서 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_c#25','math',2,1,'u1','','g2_1_math_u1_review_c','unit_review','M2-1-u1-C5',4,'essay','teacher','620부터 10씩 거꾸로 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u1-C5","difficulty":4,"kind":"essay","stem":"620부터 10씩 거꾸로 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"610, 600, 590, 580. 600에서 10 작아질 때 십의 자리가 0이라 백의 자리에서 1을 빌려 와 590이 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#1','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C1',1,'mc','auto','98보다 2만큼 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X12']::text[],false,'{"seq":1,"concept":"M2-1-u1-C1","difficulty":1,"kind":"mc","stem":"98보다 2만큼 더 큰 수는 무엇인가요?","options":[{"t":"100","correct":true},{"t":"99","mis":"M2-1-u1-X12"},{"t":"108","mis":"M2-1-u1-X12"}],"explanation":["98, 99, 100 — 1씩 두 번 뛰어요.","98보다 2 큰 수는 100이에요.","얼마만큼 큰지 잘 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#2','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C2',1,'mc','auto','100이 9개이면 얼마인가요?',ARRAY['M2-1-u1-X03']::text[],true,'{"seq":2,"concept":"M2-1-u1-C2","difficulty":1,"kind":"mc","stem":"100이 9개이면 얼마인가요?","options":[{"t":"900","correct":true},{"t":"109","mis":"M2-1-u1-X03"},{"t":"90","mis":"M2-1-u1-X03"}],"explanation":["100이 9개이면 900이에요.","「구백」이라고 읽어요.","개수는 백의 자리에 쓰고, 십·일의 자리는 0이에요."],"variant_rule":{"n3":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#3','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X06','M2-1-u1-X05']::text[],true,'{"seq":3,"concept":"M2-1-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"473","correct":true},{"t":"374","mis":"M2-1-u1-X06"},{"t":"400703","mis":"M2-1-u1-X05"}],"explanation":["100이 4개, 10이 7개, 1이 3개예요.","백의 자리 4, 십의 자리 7, 일의 자리 3 — 473이에요.","백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks3","h":4,"t":7,"o":3},"variant_rule":{"n3":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#4','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-1-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"415","r":"사백십오"},{"l":"405","r":"사백오"},{"l":"450","r":"사백오십"}],"mis":"M2-1-u1-X07","explanation":["415는 「사백십오」예요.","405는 「사백오」, 450은 「사백오십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#5','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C4',1,'mc','auto','927에서 십의 자리 숫자는 무엇인가요?',ARRAY['M2-1-u1-X08','M2-1-u1-X09']::text[],true,'{"seq":5,"concept":"M2-1-u1-C4","difficulty":1,"kind":"mc","stem":"927에서 십의 자리 숫자는 무엇인가요?","options":[{"t":"2","correct":true},{"t":"7","mis":"M2-1-u1-X08"},{"t":"20","mis":"M2-1-u1-X09"}],"explanation":["927은 백의 자리 9, 십의 자리 2, 일의 자리 7이에요.","십의 자리 숫자는 2예요.","자리는 왼쪽부터 백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv3":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#6','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C5',1,'mc','auto','100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X11']::text[],true,'{"seq":6,"concept":"M2-1-u1-C5","difficulty":1,"kind":"mc","stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"570","correct":true},{"t":"471","mis":"M2-1-u1-X11"},{"t":"480","mis":"M2-1-u1-X11"}],"explanation":["100씩 뛰면 백의 자리 숫자가 1씩 커져요.","470에서 100만큼 뛰면 570이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[170,270,370,470,null],"step":100},"variant_rule":{"skip3":{"ask":"next","step":[100]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#7','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C6',1,'mc','auto','346과 364 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-1-u1-X13']::text[],true,'{"seq":7,"concept":"M2-1-u1-C6","difficulty":1,"kind":"mc","stem":"346과 364 중에서 더 큰 수는 무엇인가요?","options":[{"t":"364","correct":true},{"t":"346","mis":"M2-1-u1-X13"}],"explanation":["백의 자리가 같아요.","십의 자리를 보면 6은 4보다 커요 — 더 큰 수는 364예요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp3d":{"ask":"big","same":"h"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#8','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C2',1,'sa','auto','200은 100이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-1-u1-C2","difficulty":1,"kind":"sa","stem":"200은 100이 몇 개인가요?","answer":["2","2개"],"explanation":["200은 백의 자리 숫자가 2예요.","100이 2개예요.","백의 자리 숫자가 100의 개수예요."],"variant_rule":{"n3":{"ask":"hcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#9','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C1',2,'blank','auto','100은 80보다 (        )만큼 더 큰 수예요.',ARRAY['M2-1-u1-X12']::text[],false,'{"seq":9,"concept":"M2-1-u1-C1","difficulty":2,"kind":"blank","stem":"100은 80보다 (        )만큼 더 큰 수예요.","options":[{"t":"20","correct":true},{"t":"2","mis":"M2-1-u1-X12"},{"t":"10","mis":"M2-1-u1-X12"}],"explanation":["80, 90, 100 — 10씩 두 번 뛰어요.","그래서 100은 80보다 20 커요.","10씩 몇 번 뛰었는지 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#10','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C3',2,'mc','auto','「오백삼십」을 수로 쓰면 무엇인가요?',ARRAY['M2-1-u1-X05','M2-1-u1-X04']::text[],true,'{"seq":10,"concept":"M2-1-u1-C3","difficulty":2,"kind":"mc","stem":"「오백삼십」을 수로 쓰면 무엇인가요?","options":[{"t":"530","correct":true},{"t":"50030","mis":"M2-1-u1-X05"},{"t":"53","mis":"M2-1-u1-X04"}],"explanation":["「오백삼십」은 100이 5개, 10이 3개, 1이 0개예요.","수로 쓰면 530이에요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n3":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#11','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C4',2,'mc','auto','695에서 숫자 5가 나타내는 값은 얼마인가요?',ARRAY['M2-1-u1-X08']::text[],true,'{"seq":11,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"695에서 숫자 5가 나타내는 값은 얼마인가요?","options":[{"t":"5","correct":true},{"t":"500","mis":"M2-1-u1-X08"},{"t":"50","mis":"M2-1-u1-X08"}],"explanation":["숫자 5는 일의 자리에 있어요.","일의 자리 5는 5를 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv3":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#12','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C4',2,'mc','auto','237을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u1-X09','M2-1-u1-X08']::text[],true,'{"seq":12,"concept":"M2-1-u1-C4","difficulty":2,"kind":"mc","stem":"237을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"200 + 30 + 7","correct":true},{"t":"2 + 3 + 7","mis":"M2-1-u1-X09"},{"t":"200 + 70 + 3","mis":"M2-1-u1-X08"}],"explanation":["237은 백의 자리 2, 십의 자리 3, 일의 자리 7이에요.","각 자리의 값은 200, 30, 7 — 237 = 200 + 30 + 7.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv3":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#13','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C5',2,'mc','auto','얼마씩 거꾸로 뛰어 세었나요?',ARRAY['M2-1-u1-X12']::text[],true,'{"seq":13,"concept":"M2-1-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 거꾸로 뛰어 세었나요?","options":[{"t":"10씩","correct":true},{"t":"1씩","mis":"M2-1-u1-X12"},{"t":"100씩","mis":"M2-1-u1-X12"}],"explanation":["680, 670, 660 … 하고 십의 자리 숫자만 1씩 작아져요.","그래서 10씩 거꾸로 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[680,670,660,650,640],"step":null,"dir":"down"},"variant_rule":{"skip3":{"ask":"step","step":[1,10,100],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#14','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-1-u1-X14']::text[],true,'{"seq":14,"concept":"M2-1-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"299 < 301","correct":true},{"t":"299 > 301","mis":"M2-1-u1-X14"}],"explanation":["백의 자리에서 처음으로 달라요 — 3은 2보다 커요.","그래서 301은 299보다 커요 — 299 < 301.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp3d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#15','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C2',2,'error','auto','친구들이 몇백에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u1-X03','M2-1-u1-X07','M2-1-u1-X12']::text[],false,'{"seq":15,"concept":"M2-1-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇백에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온: 600은 100이 60개야.","correct":true,"mis_target":"M2-1-u1-X03"},{"t":"나은: 600은 「육백」이라고 읽어.","mis":"M2-1-u1-X07"},{"t":"세아: 600은 500보다 100 큰 수야.","mis":"M2-1-u1-X12"}],"explanation":["600은 백의 자리 숫자가 6이에요.","그래서 100이 6개예요 — 60개가 아니에요.","라온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#16','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C7',2,'mc','auto','10이 45개인 수는 얼마인가요?',ARRAY['M2-1-u1-X02','M2-1-u1-X10']::text[],true,'{"seq":16,"concept":"M2-1-u1-C7","difficulty":2,"kind":"mc","stem":"10이 45개인 수는 얼마인가요?","options":[{"t":"450","correct":true},{"t":"1045","mis":"M2-1-u1-X02"},{"t":"45","mis":"M2-1-u1-X10"}],"explanation":["10이 10개면 100이에요.","10이 45개는 100이 4개, 10이 5개 — 450이에요.","10이 10개 넘게 모이면 100으로 바꿔 세요."],"variant_rule":{"n3":{"ask":"tens"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#17','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C5',3,'mc','auto','1씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-1-u1-X01','M2-1-u1-X11']::text[],true,'{"seq":17,"concept":"M2-1-u1-C5","difficulty":3,"kind":"mc","stem":"1씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"799","correct":true},{"t":"809","mis":"M2-1-u1-X01"},{"t":"790","mis":"M2-1-u1-X11"}],"explanation":["1씩 거꾸로 뛰면 일의 자리 숫자가 1씩 작아져요.","800에서 1만큼 거꾸로 뛰면 799예요.","일의 자리가 0에서 더 작아지면 바로 윗자리에서 1을 빌려 와요."],"asset":{"type":"jump_row","cells":[802,801,800,null,798],"step":1,"dir":"down"},"variant_rule":{"skip3":{"ask":"blank","step":[1],"cross":true,"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#18','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C6',3,'mc','auto','599, 602, 611 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],true,'{"seq":18,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"599, 602, 611 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"599","correct":true},{"t":"602","mis":"M2-1-u1-X13"},{"t":"611","mis":"M2-1-u1-X15"}],"explanation":["높은 자리(백의 자리)부터 차례로 견주어요.","가장 작은 수는 599예요.","일의 자리가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp3d":{"ask":"min3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#19','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C7',3,'mc','auto','동전은 모두 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":19,"concept":"M2-1-u1-C7","difficulty":3,"kind":"mc","stem":"동전은 모두 얼마인가요?","options":[{"t":"492원","correct":true},{"t":"4812원","mis":"M2-1-u1-X10"},{"t":"482원","mis":"M2-1-u1-X10"}],"explanation":["1원짜리 12개는 10원짜리 1개와 1원짜리 2개로 바꿀 수 있어요.","100원짜리 4개, 10원짜리 9개, 1원짜리 2개 — 492원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":4,"t":8,"o":12,"unit":"coin"},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#20','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-1-u1-X10']::text[],true,'{"seq":20,"concept":"M2-1-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"573","correct":true},{"t":"5613","mis":"M2-1-u1-X10"},{"t":"563","mis":"M2-1-u1-X10"}],"explanation":["일 모형 13개는 십 모형 1개와 일 모형 3개로 바꿀 수 있어요.","100이 5개, 10이 7개, 1이 3개 — 573이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks3","h":5,"t":6,"o":13},"variant_rule":{"n3":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#21','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C4',3,'ox','auto','622에서 두 숫자 2가 나타내는 값은 20과 2예요.',ARRAY['M2-1-u1-X09']::text[],false,'{"seq":21,"concept":"M2-1-u1-C4","difficulty":3,"kind":"ox","stem":"622에서 두 숫자 2가 나타내는 값은 20과 2예요.","answer":"O","reason_options":[{"t":"십의 자리 2는 20, 일의 자리 2는 2니까","correct":true},{"t":"같은 숫자는 값도 같으니까","mis":"M2-1-u1-X09"}],"mis":"M2-1-u1-X09","explanation":["가운데 2는 십의 자리라 20이에요.","끝의 2는 일의 자리라 2예요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#22','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C6',3,'mc','auto','수 카드 0, 8, 4를 한 번씩 모두 써서 만들 수 있는 가장 큰 세 자리 수는 무엇인가요?',ARRAY['M2-1-u1-X15','M2-1-u1-X16']::text[],true,'{"seq":22,"concept":"M2-1-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 0, 8, 4를 한 번씩 모두 써서 만들 수 있는 가장 큰 세 자리 수는 무엇인가요?","options":[{"t":"840","correct":true},{"t":"408","mis":"M2-1-u1-X15"},{"t":"804","mis":"M2-1-u1-X16"}],"explanation":["가장 큰 8을 백의 자리에 놓아요.","남은 카드도 큰 수부터 — 840이에요.","높은 자리일수록 큰 숫자를 놓아요."],"variant_rule":{"cards3":{"ask":"max","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#23','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C7',4,'mc','auto','100원짜리 동전 5개와 10원짜리 동전 6개를 모두 10원짜리 동전으로 바꾸면 몇 개가 되나요?',ARRAY['M2-1-u1-X03','M2-1-u1-X04']::text[],false,'{"seq":23,"concept":"M2-1-u1-C7","difficulty":4,"kind":"mc","stem":"100원짜리 동전 5개와 10원짜리 동전 6개를 모두 10원짜리 동전으로 바꾸면 몇 개가 되나요?","options":[{"t":"56","correct":true},{"t":"11","mis":"M2-1-u1-X03"},{"t":"506","mis":"M2-1-u1-X04"}],"explanation":["100원짜리 하나는 10원짜리 10개예요.","100원짜리 5개는 10원짜리 50개 — 6개를 더하면 56개예요.","560원은 10이 56개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#24','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C6',4,'mc','auto','2□6은 285보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-1-u1-X13','M2-1-u1-X15']::text[],false,'{"seq":24,"concept":"M2-1-u1-C6","difficulty":4,"kind":"mc","stem":"2□6은 285보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"1","mis":"M2-1-u1-X13"},{"t":"8","mis":"M2-1-u1-X15"}],"explanation":["백의 자리는 2로 같으니 십의 자리를 견주어요.","□가 8이면 286 — 285보다 커요. □는 8, 9예요.","그래서 모두 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u1_review_d#25','math',2,1,'u1','','g2_1_math_u1_review_d','unit_review','M2-1-u1-C5',4,'essay','teacher','803부터 1씩 거꾸로 5번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u1-C5","difficulty":4,"kind":"essay","stem":"803부터 1씩 거꾸로 5번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"802, 801, 800, 799, 798. 800에서 1 작아질 때 일·십의 자리가 0이라 백의 자리에서 빌려 와 799가 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
